#!/usr/bin/env python3
"""Differential tmux runner.
Usage: run.py SPEC.json [orig|mine|both]
SPEC: {"name":..., "w":100, "h":30, "args":[...], "files":{"relpath": "content"}, "keys":[...], "env":{}}
keys entries: "L:text" literal, "S:0.5" sleep, "SNAP" capture, other: tmux key names
Paths: files relative to run dir; HOME=rundir/home, cwd=rundir/work
"""
import sys, json, subprocess, time, os, shutil
ORIG = "/workspace/executable"
MINE = os.environ.get("MINE", "/workspace/target/release/tjournal")
def tm(*a):
    return subprocess.run(["tmux"]+list(a), capture_output=True, text=True).stdout
def run(spec, which):
    name = spec.get("name", "x") + "_" + which
    rd = f"/tmp/runs/{name}"
    shutil.rmtree(rd, ignore_errors=True)
    os.makedirs(rd + "/home", exist_ok=True)
    os.makedirs(rd + "/work", exist_ok=True)
    for p, c in spec.get("files", {}).items():
        fp = os.path.join(rd, p)
        os.makedirs(os.path.dirname(fp), exist_ok=True)
        open(fp, "w").write(c)
    binp = ORIG if which == "orig" else MINE
    args = " ".join("'" + a.replace("RD", rd) + "'" for a in spec.get("args", []))
    env = {"HOME": rd + "/home", "TERM": "xterm-256color"}
    env.update(spec.get("env", {}))
    envs = " ".join(f"{k}='{v}'" for k, v in env.items())
    sess = "r_" + name
    tm("kill-session", "-t", sess)
    tm("new-session", "-d", "-s", sess, "-x", str(spec.get("w", 100)), "-y", str(spec.get("h", 30)), "-c", rd + "/work",
       f"env {envs} {binp} {args}; echo EXITED rc=$?; sleep 30")
    time.sleep(spec.get("startdelay", 0.6))
    snaps = []
    delay = spec.get("delay", 0.12)
    for k in spec.get("keys", []) + ["SNAP"]:
        if k == "SNAP":
            time.sleep(0.4)
            snaps.append(tm("capture-pane", "-t", sess, "-p", "-e" if spec.get("color", True) else "-p"))
            continue
        if k.startswith("L:"):
            tm("send-keys", "-t", sess, "-l", k[2:])
        elif k.startswith("S:"):
            time.sleep(float(k[2:])); continue
        elif k.startswith("RESIZE:"):
            w, h = k[7:].split("x"); tm("resize-window", "-t", sess, "-x", w, "-y", h)
        else:
            tm("send-keys", "-t", sess, k)
        time.sleep(delay)
    tm("kill-session", "-t", sess)
    files = {}
    for root, dirs, fs in os.walk(rd):
        for f in fs:
            p = os.path.join(root, f)
            if p.endswith(".log"): continue
            try: files[os.path.relpath(p, rd)] = open(p, errors="replace").read()
            except Exception as e: files[os.path.relpath(p, rd)] = f"<{e}>"
    return snaps, files
if __name__ == "__main__":
    spec = json.load(open(sys.argv[1]))
    which = sys.argv[2] if len(sys.argv) > 2 else "both"
    res = {}
    for w in (["orig", "mine"] if which == "both" else [which]):
        res[w] = run(spec, w)
    if which != "both":
        snaps, files = res[which]
        for i, s in enumerate(snaps):
            print(f"--- snap {i}"); print(s.rstrip("\n"))
        for f, c in sorted(files.items()):
            print(f"--- file {f}"); print(c)
    else:
        ok = True
        (s1, f1), (s2, f2) = res["orig"], res["mine"]
        for i, (a, b) in enumerate(zip(s1, s2)):
            if a != b:
                ok = False
                print(f"=== snap {i} differs")
                import difflib
                for l in difflib.unified_diff(a.split("\n"), b.split("\n"), "orig", "mine", lineterm="", n=0):
                    print(l)
        for f in sorted(set(f1) | set(f2)):
            a = f1.get(f, "<missing>"); b = f2.get(f, "<missing>")
            if a != b:
                ok = False
                print(f"=== file {f} differs\n orig: {a[:2000]!r}\n mine: {b[:2000]!r}")
        print("SAME" if ok else "DIFF")
EOF
chmod +x /tmp/tt/run.py; echo ok"}

