import re, sys
def parse(text):
    """parse tmux capture -e output into rows of [(ch, fg, bg, attrs)]"""
    rows = []
    for line in text.split("\n"):
        fg = bg = None; attrs = set()
        cells = []
        i = 0
        while i < len(line):
            m = re.match(r"\x1b\[([0-9;]*)m", line[i:])
            if m:
                params = m.group(1).split(";") if m.group(1) else ["0"]
                j = 0
                while j < len(params):
                    p = int(params[j]) if params[j] else 0
                    if p == 0: fg = bg = None; attrs = set()
                    elif p == 38: 
                        if params[j+1] == "5": fg = params[j+2]; j += 2
                        else: fg = "#%02x%02x%02x" % tuple(map(int, params[j+2:j+5])); j += 4
                    elif p == 48:
                        if params[j+1] == "5": bg = params[j+2]; j += 2
                        else: bg = "#%02x%02x%02x" % tuple(map(int, params[j+2:j+5])); j += 4
                    elif p == 39: fg = None
                    elif p == 49: bg = None
                    elif 30 <= p <= 37: fg = str(p-30)
                    elif 40 <= p <= 47: bg = str(p-40)
                    elif 90 <= p <= 97: fg = str(p-90+8)
                    elif 100 <= p <= 107: bg = str(p-100+8)
                    elif p in (22,): attrs.discard(1); attrs.discard(2)
                    elif p in (23,24,25,27,28,29): attrs.discard(p-20)
                    else: attrs.add(p)
                    j += 1
                i += m.end(); continue
            cells.append((line[i], fg, bg, frozenset(attrs)))
            i += 1
        rows.append(cells)
    return rows
def mark(text, c0=0, c1=10000, r0=0, r1=10000):
    rows = parse(text)
    out = []
    for r in rows[r0:r1]:
        s = ""
        prev = None
        for (ch, fg, bg, at) in r[c0:c1]:
            key = (bg,) if bg else None
            if key != prev:
                if prev: s += "}"
                if key: s += "{" + str(bg) + ":"
                prev = key
            s += ch
        if prev: s += "}"
        out.append(s.rstrip())
    return "\n".join(out)
if __name__ == "__main__":
    a = sys.argv[1:]
    print(mark(sys.stdin.read(), *map(int, a)))
EOF
