//! Text wrapping compatible with the behaviour observed in the original application.
//! Implements word finding using (a subset of) the Unicode line breaking algorithm,
//! hyphen splitting, long word breaking and the optimal-fit wrapping algorithm.

use unicode_width::UnicodeWidthChar;
use unicode_width::UnicodeWidthStr;

#[derive(Clone, Debug)]
struct Word<'a> {
    word: &'a str,
    whitespace: &'a str,
    penalty: &'a str,
    width: usize,
}

impl<'a> Word<'a> {
    fn from(word: &'a str) -> Word<'a> {
        let trimmed = word.trim_end_matches(' ');
        Word {
            word: trimmed,
            width: display_width(trimmed),
            whitespace: &word[trimmed.len()..],
            penalty: "",
        }
    }
    fn width(&self) -> f64 {
        self.width as f64
    }
    fn whitespace_width(&self) -> f64 {
        self.whitespace.len() as f64
    }
    fn penalty_width(&self) -> f64 {
        display_width(self.penalty) as f64
    }

    fn break_apart(&self, line_width: usize) -> Vec<Word<'a>> {
        let mut out = Vec::new();
        let mut start = 0;
        let mut width = 0;
        for (idx, ch) in self.word.char_indices() {
            let cw = ch_width(ch);
            if width > 0 && width + cw > line_width {
                out.push(Word {
                    word: &self.word[start..idx],
                    width,
                    whitespace: "",
                    penalty: "",
                });
                start = idx;
                width = cw;
            } else {
                width += cw;
            }
        }
        if start < self.word.len() {
            out.push(Word {
                word: &self.word[start..],
                width,
                whitespace: self.whitespace,
                penalty: self.penalty,
            });
        }
        out
    }
}

pub fn display_width(s: &str) -> usize {
    s.chars().map(ch_width).sum()
}

fn ch_width(ch: char) -> usize {
    ch.width().unwrap_or(0)
}

#[allow(dead_code)]
pub fn str_width(s: &str) -> usize {
    UnicodeWidthStr::width(s)
}

// ---------------------------------------------------------------------------
// Line breaking classes (simplified UAX #14)

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Lb {
    Sp,
    Ba,
    Hy,
    Ex,
    Qu,
    Al,
    Nu,
    Is,
    Sy,
    Op,
    Cp,
    Cl,
    Pr,
    Po,
    Id,
    Gl,
    Ns,
    Bb,
    Cm,
    Zw,
    Wj,
}

fn lb_class(c: char) -> Lb {
    match c {
        ' ' => Lb::Sp,
        '\t' => Lb::Ba,
        '|' => Lb::Ba,
        '-' => Lb::Hy,
        '!' | '?' => Lb::Ex,
        '"' | '\'' => Lb::Qu,
        '0'..='9' => Lb::Nu,
        ',' | '.' | ':' | ';' => Lb::Is,
        '/' => Lb::Sy,
        '(' | '[' => Lb::Op,
        '{' => Lb::Op,
        ')' | ']' => Lb::Cp,
        '}' => Lb::Cl,
        '$' | '+' | '\\' => Lb::Pr,
        '%' => Lb::Po,
        '\u{00A0}' | '\u{202F}' | '\u{2007}' | '\u{2011}' => Lb::Gl,
        '\u{200B}' => Lb::Zw,
        '\u{2060}' | '\u{FEFF}' => Lb::Wj,
        '\u{00AD}' => Lb::Ba,
        '\u{2010}' | '\u{2012}' | '\u{2013}' => Lb::Ba,
        '\u{2014}' => Lb::Ba,
        '\u{00B4}' => Lb::Bb,
        '\u{2018}' | '\u{2019}' | '\u{201C}' | '\u{201D}' | '\u{00AB}' | '\u{00BB}' => Lb::Qu,
        '\u{3001}' | '\u{3002}' | '\u{FF0C}' | '\u{FF0E}' => Lb::Cl,
        '\u{3005}' | '\u{3041}' | '\u{3043}' | '\u{3045}' | '\u{3047}' | '\u{3049}' => Lb::Ns,
        '\u{0300}'..='\u{036F}' | '\u{200D}' | '\u{FE00}'..='\u{FE0F}' => Lb::Cm,
        '\u{1100}'..='\u{115F}'
        | '\u{2E80}'..='\u{2FFF}'
        | '\u{3040}'..='\u{30FF}'
        | '\u{3100}'..='\u{31FF}'
        | '\u{3200}'..='\u{4DBF}'
        | '\u{4E00}'..='\u{9FFF}'
        | '\u{A000}'..='\u{A4CF}'
        | '\u{AC00}'..='\u{D7A3}'
        | '\u{F900}'..='\u{FAFF}'
        | '\u{FF01}'..='\u{FF60}'
        | '\u{1F300}'..='\u{1F64F}'
        | '\u{1F900}'..='\u{1F9FF}'
        | '\u{20000}'..='\u{3FFFD}' => Lb::Id,
        _ => Lb::Al,
    }
}

/// Returns byte indices after which a line break is allowed (excluding the end of text).
fn break_opportunities(line: &str) -> Vec<usize> {
    let chars: Vec<(usize, char)> = line.char_indices().collect();
    let mut res = Vec::new();
    if chars.is_empty() {
        return res;
    }
    let classes: Vec<Lb> = chars.iter().map(|(_, c)| lb_class(*c)).collect();
    // resolve combining marks: treat as previous class (LB9) or AL at start (LB10)
    let mut cls: Vec<Lb> = Vec::with_capacity(classes.len());
    for (i, c) in classes.iter().enumerate() {
        if *c == Lb::Cm {
            if i == 0 {
                cls.push(Lb::Al);
            } else {
                let prev = cls[i - 1];
                if prev == Lb::Sp || prev == Lb::Zw {
                    cls.push(Lb::Al);
                } else {
                    cls.push(prev);
                }
            }
        } else {
            cls.push(*c);
        }
    }

    for i in 1..chars.len() {
        // decide whether a break is allowed between i-1 and i
        let before = cls[i - 1];
        let after = cls[i];
        if classes[i] == Lb::Cm && cls[i - 1] != Lb::Sp {
            continue; // LB9
        }
        // find last non-space class before position (for SP* rules)
        let mut j = i as isize - 1;
        while j >= 0 && cls[j as usize] == Lb::Sp {
            j -= 1;
        }
        let before_sp = if j >= 0 { Some(cls[j as usize]) } else { None };
        let allowed = (|| {
            // LB7
            if after == Lb::Sp || after == Lb::Zw {
                return false;
            }
            // LB8
            if before_sp == Some(Lb::Zw) {
                return true;
            }
            // LB11
            if after == Lb::Wj || before == Lb::Wj {
                return false;
            }
            // LB12
            if before == Lb::Gl {
                return false;
            }
            // LB12a
            if after == Lb::Gl && !matches!(before, Lb::Sp | Lb::Ba | Lb::Hy) {
                return false;
            }
            // LB13
            if matches!(after, Lb::Cl | Lb::Cp | Lb::Ex | Lb::Is | Lb::Sy) {
                return false;
            }
            // LB14
            if before_sp == Some(Lb::Op) {
                return false;
            }
            // LB15
            if before_sp == Some(Lb::Qu) && after == Lb::Op {
                return false;
            }
            // LB16
            if matches!(before_sp, Some(Lb::Cl) | Some(Lb::Cp)) && after == Lb::Ns {
                return false;
            }
            // LB18
            if before == Lb::Sp {
                return true;
            }
            // LB19
            if after == Lb::Qu || before == Lb::Qu {
                return false;
            }
            // LB21
            if matches!(after, Lb::Ba | Lb::Hy | Lb::Ns) || before == Lb::Bb {
                return false;
            }
            // LB23
            if (before == Lb::Al && after == Lb::Nu) || (before == Lb::Nu && after == Lb::Al) {
                return false;
            }
            // LB23a
            if before == Lb::Pr && after == Lb::Id {
                return false;
            }
            if before == Lb::Id && after == Lb::Po {
                return false;
            }
            // LB24
            if matches!(before, Lb::Pr | Lb::Po) && after == Lb::Al {
                return false;
            }
            if before == Lb::Al && matches!(after, Lb::Pr | Lb::Po) {
                return false;
            }
            // LB25 (simplified pair-table version)
            if matches!(
                (before, after),
                (Lb::Cl, Lb::Po)
                    | (Lb::Cp, Lb::Po)
                    | (Lb::Cl, Lb::Pr)
                    | (Lb::Cp, Lb::Pr)
                    | (Lb::Nu, Lb::Po)
                    | (Lb::Nu, Lb::Pr)
                    | (Lb::Po, Lb::Op)
                    | (Lb::Po, Lb::Nu)
                    | (Lb::Pr, Lb::Op)
                    | (Lb::Pr, Lb::Nu)
                    | (Lb::Hy, Lb::Nu)
                    | (Lb::Is, Lb::Nu)
                    | (Lb::Nu, Lb::Nu)
                    | (Lb::Sy, Lb::Nu)
            ) {
                return false;
            }
            // LB28
            if before == Lb::Al && after == Lb::Al {
                return false;
            }
            // LB29
            if before == Lb::Is && after == Lb::Al {
                return false;
            }
            // LB30
            if matches!(before, Lb::Al | Lb::Nu) && after == Lb::Op {
                return false;
            }
            if before == Lb::Cp && matches!(after, Lb::Al | Lb::Nu) {
                return false;
            }
            true
        })();
        if allowed {
            res.push(chars[i].0);
        }
    }
    res
}

fn find_words(line: &str) -> Vec<Word<'_>> {
    let opportunities: Vec<usize> = break_opportunities(line)
        .into_iter()
        .filter(|idx| {
            let prev = line[..*idx].chars().next_back();
            !matches!(prev, Some('-') | Some('\u{00AD}'))
        })
        .collect();
    let mut words = Vec::new();
    let mut start = 0;
    for idx in opportunities {
        words.push(Word::from(&line[start..idx]));
        start = idx;
    }
    if start < line.len() {
        words.push(Word::from(&line[start..]));
    }
    words
}

fn split_points(word: &str) -> Vec<usize> {
    let mut splits = Vec::new();
    for (idx, _) in word.match_indices('-') {
        let prev = word[..idx].chars().next_back();
        let next = word[idx + 1..].chars().next();
        if prev.filter(|ch| ch.is_alphanumeric()).is_some()
            && next.filter(|ch| ch.is_alphanumeric()).is_some()
        {
            splits.push(idx + 1);
        }
    }
    splits
}

fn split_words<'a>(words: Vec<Word<'a>>) -> Vec<Word<'a>> {
    let mut out = Vec::new();
    for word in words {
        let mut prev = 0;
        for idx in split_points(word.word) {
            let need_hyphen = !word.word[..idx].ends_with('-');
            out.push(Word {
                word: &word.word[prev..idx],
                width: display_width(&word.word[prev..idx]),
                whitespace: "",
                penalty: if need_hyphen { "-" } else { "" },
            });
            prev = idx;
        }
        if prev < word.word.len() || prev == 0 {
            out.push(Word {
                word: &word.word[prev..],
                width: display_width(&word.word[prev..]),
                whitespace: word.whitespace,
                penalty: word.penalty,
            });
        }
    }
    out
}

fn break_words<'a>(words: Vec<Word<'a>>, line_width: usize) -> Vec<Word<'a>> {
    let mut out = Vec::new();
    for word in words {
        if word.width() > line_width as f64 {
            out.extend(word.break_apart(line_width));
        } else {
            out.push(word);
        }
    }
    out
}

// ---------------------------------------------------------------------------
// SMAWK based optimal fit

fn smawk_inner<M: Fn(usize, usize) -> f64>(
    matrix: &M,
    rows: &[usize],
    cols: &[usize],
    minima: &mut [usize],
) {
    if cols.is_empty() {
        return;
    }
    let mut stack: Vec<usize> = Vec::with_capacity(cols.len());
    for r in rows {
        while !stack.is_empty()
            && matrix(stack[stack.len() - 1], cols[stack.len() - 1])
                > matrix(*r, cols[stack.len() - 1])
        {
            stack.pop();
        }
        if stack.len() != cols.len() {
            stack.push(*r);
        }
    }
    let rows = &stack;
    let mut odd_cols = Vec::with_capacity(1 + cols.len() / 2);
    for (idx, c) in cols.iter().enumerate() {
        if idx % 2 == 1 {
            odd_cols.push(*c);
        }
    }
    smawk_inner(matrix, rows, &odd_cols, minima);
    let mut r = 0;
    for (c, &col) in cols.iter().enumerate().filter(|(c, _)| c % 2 == 0) {
        let mut row = rows[r];
        let last_row = if c == cols.len() - 1 {
            rows[rows.len() - 1]
        } else {
            minima[cols[c + 1]]
        };
        let mut pair = (matrix(row, col), row);
        while row != last_row {
            r += 1;
            row = rows[r];
            let v = (matrix(row, col), row);
            if v.0 < pair.0 || (v.0 == pair.0 && v.1 < pair.1) {
                pair = v;
            }
        }
        minima[col] = pair.1;
    }
}

fn online_column_minima<M: Fn(&[(usize, f64)], usize, usize) -> f64>(
    initial: f64,
    size: usize,
    matrix: M,
) -> Vec<(usize, f64)> {
    let mut result = vec![(0usize, initial)];
    if size == 0 {
        return result;
    }
    let mut finished = 0;
    let mut base = 0;
    let mut tentative = 0;
    while finished < size - 1 {
        let i = finished + 1;
        if i > tentative {
            let rows = (base..finished + 1).collect::<Vec<_>>();
            tentative = std::cmp::min(finished + rows.len(), size - 1);
            let cols = (finished + 1..tentative + 1).collect::<Vec<_>>();
            let mut minima = vec![0; tentative + 1];
            {
                let res_ref = &result;
                let fin = finished;
                let m = |i: usize, j: usize| matrix(&res_ref[..fin + 1], i, j);
                smawk_inner(&m, &rows, &cols, &mut minima);
            }
            for col in cols {
                let row = minima[col];
                let v = matrix(&result[..finished + 1], row, col);
                if col >= result.len() {
                    result.push((row, v));
                } else if v < result[col].1 {
                    result[col] = (row, v);
                }
            }
            finished = i;
            continue;
        }
        let diag = matrix(&result[..finished + 1], i - 1, i);
        if diag < result[i].1 {
            result[i] = (i - 1, diag);
            base = i - 1;
            tentative = i;
            finished = i;
            continue;
        }
        if matrix(&result[..finished + 1], i - 1, tentative) >= result[tentative].1 {
            finished = i;
            continue;
        }
        base = i - 1;
        tentative = i;
        finished = i;
    }
    result
}

fn wrap_optimal_fit<'a, 'b>(fragments: &'b [Word<'a>], line_width: f64) -> Vec<&'b [Word<'a>]> {
    const NLINE_PENALTY: f64 = 1000.0;
    const OVERFLOW_PENALTY: f64 = 2500.0;
    const SHORT_LAST_LINE_FRACTION: f64 = 4.0;
    const SHORT_LAST_LINE_PENALTY: f64 = 25.0;
    const HYPHEN_PENALTY: f64 = 25.0;

    let mut widths = Vec::with_capacity(fragments.len() + 1);
    let mut width = 0.0;
    widths.push(width);
    for f in fragments {
        width += f.width() + f.whitespace_width();
        widths.push(width);
    }
    let target_width = line_width.max(1.0);
    let minima = online_column_minima(0.0, widths.len(), |minima, i, j| {
        let lw = widths[j] - widths[i] - fragments[j - 1].whitespace_width()
            + fragments[j - 1].penalty_width();
        let mut cost = minima[i].1 + NLINE_PENALTY;
        if lw > target_width {
            let overflow = lw - target_width;
            cost += overflow * OVERFLOW_PENALTY;
        } else if j < fragments.len() {
            let gap = target_width - lw;
            cost += gap * gap;
        } else if i + 1 == j && lw < target_width / SHORT_LAST_LINE_FRACTION {
            cost += SHORT_LAST_LINE_PENALTY;
        }
        if fragments[j - 1].penalty_width() > 0.0 {
            cost += HYPHEN_PENALTY;
        }
        cost
    });
    let mut lines = Vec::new();
    let mut pos = fragments.len();
    loop {
        let prev = minima[pos].0;
        lines.push(&fragments[prev..pos]);
        pos = prev;
        if pos == 0 {
            break;
        }
    }
    lines.reverse();
    lines
}

fn wrap_single_line(line: &str, width: usize, lines: &mut Vec<String>) {
    if line.len() < width {
        lines.push(line.trim_end_matches(' ').to_string());
        return;
    }
    let words = find_words(line);
    let split = split_words(words);
    let broken = break_words(split, width);
    let wrapped = wrap_optimal_fit(&broken, width as f64);
    let mut idx = 0;
    for words in wrapped {
        let last_word = match words.last() {
            None => {
                lines.push(String::new());
                continue;
            }
            Some(w) => w,
        };
        let len = words
            .iter()
            .map(|w| w.word.len() + w.whitespace.len())
            .sum::<usize>()
            - last_word.whitespace.len();
        let mut result = line[idx..idx + len].to_string();
        if !last_word.penalty.is_empty() {
            result.push_str(last_word.penalty);
        }
        lines.push(result);
        idx += len + last_word.whitespace.len();
    }
}

/// Wraps the text into lines with the given width (like textwrap::wrap with default options)
pub fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut lines = Vec::new();
    for line in text.split('\n') {
        wrap_single_line(line, width, &mut lines);
    }
    lines
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn basic() {
        assert_eq!(wrap("aaa bb cc ddddd", 6), vec!["aaa", "bb cc", "ddddd"]);
        assert_eq!(wrap("Enter, <Ctrl-m>", 14), vec!["Enter, <Ctrl-", "m>"]);
        assert_eq!(wrap("aaaa/bbbb/cccc/dddd", 6), vec!["aaaa/", "bbbb/", "cccc/", "dddd"]);
        assert_eq!(wrap("x 123/456/789/0", 6), vec!["x", "123/45", "6/789/", "0"]);
        assert_eq!(wrap("aaaa-bbbb-cccc", 6), vec!["aaaa-", "bbbb-", "cccc"]);
    }
}
