pub enum PendingCliCommand {
    ImportJournals(PathBuf),
    AssignPriority(u32),
}

pub enum CliCommand {
    PrintConfig,
    ThemePrintPath,
    ThemePrintDefault,
    ThemeWriteDefaults,
    Pending(PendingCliCommand),
}

pub struct Cli {
    pub json_file_path: Option<PathBuf>,
    pub sqlite_file_path: Option<PathBuf>,
