    }

    pub fn start_selection(&mut self) {
        self.selection_start = Some(self.cursor);
    }

    pub fn cancel_selection(&mut self) {
        self.selection_start = None;
    }

    #[allow(dead_code)]
    pub fn select_all(&mut self) {
        self.move_cursor(CursorMove::Jump(u16::MAX, u16::MAX));
        self.selection_start = Some((0, 0));
    }

    fn line_offset(&self, row: usize, col: usize) -> usize {
        let line = self.lines.get(row).unwrap_or(&self.lines[self.lines.len() - 1]);
        line.char_indices().nth(col).map(|(i, _)| i).unwrap_or(line.len())
    }

    fn selection_positions(&self) -> Option<(Pos, Pos)> {
        let (sr, sc) = self.selection_start?;
        let (er, ec) = self.cursor;
        let (sr, sc, er, ec) = if (er, ec) < (sr, sc) {
            (er, ec, sr, sc)
        } else {
            (sr, sc, er, ec)
        };
        let so = self.line_offset(sr, sc);
        let eo = self.line_offset(er, ec);
        Some((Pos::new(sr, sc, so), Pos::new(er, ec, eo)))
    }

    fn take_selection_positions(&mut self) -> Option<(Pos, Pos)> {
        let range = self.selection_positions();
        self.cancel_selection();
        range
    }

    pub fn selected_text(&self) -> Option<String> {
        let (start, end) = self.selection_positions()?;
        Some(self.text_in_range(start, end).join("\n"))
    }

    fn text_in_range(&self, start: Pos, end: Pos) -> Vec<String> {
        if start.row == end.row {
            vec![self.lines[start.row][start.offset..end.offset].to_string()]
        } else {
            let mut chunk = vec![self.lines[start.row][start.offset..].to_string()];
            for r in start.row + 1..end.row {
                chunk.push(self.lines[r].clone());
            }
            chunk.push(self.lines[end.row][..end.offset].to_string());
            chunk
        }
    }

    fn push_history(&mut self, kind: EditKind, before: Pos, after_offset: usize) {
        let (row, col) = self.cursor;
        let after = Pos::new(row, col, after_offset);
        let edit = Edit { kind, before, after };
        self.history.push(edit);
    }

    pub fn insert_char(&mut self, c: char) {
        if c == '\n' || c == '\r' {
            self.insert_newline();
            return;
        }
        self.delete_selection(false);
        let (row, col) = self.cursor;
        let line = &mut self.lines[row];
        let i = line
            .char_indices()
            .nth(col)
            .map(|(i, _)| i)
            .unwrap_or(line.len());
        line.insert(i, c);
        self.cursor.1 += 1;
        self.push_history(
            EditKind::InsertChar(c),
            Pos::new(row, col, i),
            i + c.len_utf8(),
        );
    }

    pub fn insert_str<S: AsRef<str>>(&mut self, s: S) -> bool {
        let modified = self.delete_selection(false);
        let mut lines: Vec<_> = s
            .as_ref()
            .split('\n')
            .map(|s| s.strip_suffix('\r').unwrap_or(s).to_string())
            .collect();
        match lines.len() {
            0 => modified,
            1 => self.insert_piece(lines.remove(0)) || modified,
            _ => self.insert_chunk(lines) || modified,
        }
    }

    fn insert_chunk(&mut self, chunk: Vec<String>) -> bool {
        debug_assert!(chunk.len() > 1);
        let (row, col) = self.cursor;
        let line = &mut self.lines[row];
        let i = line
            .char_indices()
            .nth(col)
            .map(|(i, _)| i)
            .unwrap_or(line.len());
        let before = Pos::new(row, col, i);
        let (row, col) = (
            row + chunk.len() - 1,
            chunk[chunk.len() - 1].chars().count(),
        );
        self.cursor = (row, col);
        let end_offset = chunk.last().unwrap().len();
        let edit = EditKind::InsertChunk(chunk);
        edit.apply(&mut self.lines, &before, &Pos::new(row, col, end_offset));
        self.push_history(edit, before, end_offset);
        true
    }

    fn insert_piece(&mut self, s: String) -> bool {
        if s.is_empty() {
            return false;
        }
        let (row, col) = self.cursor;
        let line = &mut self.lines[row];
        debug_assert!(!s.contains('\n'));
        let i = line
            .char_indices()
            .nth(col)
            .map(|(i, _)| i)
            .unwrap_or(line.len());
        line.insert_str(i, &s);
        let end_offset = i + s.len();
        self.cursor.1 += s.chars().count();
        self.push_history(EditKind::InsertStr(s), Pos::new(row, col, i), end_offset);
        true
    }

    fn delete_range(&mut self, start: Pos, end: Pos, should_yank: bool) {
        self.cursor = (start.row, start.col);
        if start.row == end.row {
            let removed = self.lines[start.row]
                .drain(start.offset..end.offset)
                .as_str()
                .to_string();
            if should_yank {
                self.yank = YankText::Piece(removed.clone());
            }
            self.push_history(EditKind::DeleteStr(removed), end, start.offset);
            return;
        }
        let mut deleted = vec![self.lines[start.row]
            .drain(start.offset..)
            .as_str()
            .to_string()];
        deleted.extend(self.lines.drain(start.row + 1..end.row));
        if start.row + 1 < self.lines.len() {
            let mut last_line = self.lines.remove(start.row + 1);
            self.lines[start.row].push_str(&last_line[end.offset..]);
            last_line.truncate(end.offset);
            deleted.push(last_line);
        }
        if should_yank {
            self.yank = YankText::Chunk(deleted.clone());
        }
        let edit = if deleted.len() == 1 {
            EditKind::DeleteStr(deleted.remove(0))
        } else {
            EditKind::DeleteChunk(deleted)
        };
        self.push_history(edit, end, start.offset);
    }

    pub fn delete_str(&mut self, chars: usize) -> bool {
        if self.delete_selection(false) {
            return true;
        }
        if chars == 0 {
            return false;
        }
        let (start_row, start_col) = self.cursor;
        let mut remaining = chars;
        let mut find_end = move |line: &str| {
            let mut col = 0usize;
            for (i, _) in line.char_indices() {
                if remaining == 0 {
                    return Some(i);
                }
                col += 1;
                remaining -= 1;
            }
            let _ = col;
            if remaining == 0 {
                Some(line.len())
            } else {
                remaining -= 1;
                None
            }
        };
        let line = &self.lines[start_row];
        let start_offset = line
            .char_indices()
            .nth(start_col)
            .map(|(i, _)| i)
            .unwrap_or(line.len());
        if let Some(offset) = find_end(&line[start_offset..]) {
            let end_offset = start_offset + offset;
            let removed = self.lines[start_row]
                .drain(start_offset..end_offset)
                .as_str()
                .to_string();
            self.yank = YankText::Piece(removed.clone());
            self.push_history(
                EditKind::DeleteStr(removed),
                Pos::new(start_row, start_col, start_offset),
                start_offset,
            );
            return true;
        }
        let mut r = start_row + 1;
        let mut offset = None;
        while r < self.lines.len() {
            if let Some(o) = find_end(&self.lines[r]) {
                offset = Some(o);
                break;
            }
            r += 1;
        }
        let (end_row, end_offset) = match offset {
            Some(o) => (r, o),
            None => {
                let last = self.lines.len() - 1;
                (last, self.lines[last].len())
            }
        };
        let end_col = self.lines[end_row][..end_offset].chars().count();
        let start = Pos::new(start_row, start_col, start_offset);
        let end = Pos::new(end_row, end_col, end_offset);
        self.delete_range(start, end, true);
        true
    }

    pub fn insert_newline(&mut self) {
        self.delete_selection(false);
        let (row, col) = self.cursor;
        let line = &mut self.lines[row];
        let offset = line
            .char_indices()
            .nth(col)
            .map(|(i, _)| i)
            .unwrap_or(line.len());
        let next_line = line[offset..].to_string();
        line.truncate(offset);
        self.lines.insert(row + 1, next_line);
        self.cursor = (row + 1, 0);
        self.push_history(EditKind::InsertNewline, Pos::new(row, col, offset), 0);
    }

    pub fn insert_tab(&mut self) -> bool {
        let modified = self.delete_selection(false);
        if self.tab_len == 0 {
            return modified;
        }
        if self.hard_tab_indent {
            self.insert_char('\t');
            return true;
        }
        let (row, col) = self.cursor;
        let width: usize = self.lines[row]
            .chars()
            .take(col)
            .map(|c| unicode_width::UnicodeWidthChar::width(c).unwrap_or(0))
            .sum();
        let len = self.tab_len as usize - (width % self.tab_len as usize);
        self.insert_piece(" ".repeat(len))
    }

    pub fn delete_char(&mut self) -> bool {
        if self.delete_selection(false) {
            return true;
        }
        let (row, col) = self.cursor;
        if col == 0 {
            if row > 0 {
                let line = self.lines.remove(row);
                let prev_line = &mut self.lines[row - 1];
                let prev_line_end = prev_line.len();
                self.cursor = (row - 1, prev_line.chars().count());
                prev_line.push_str(&line);
                self.push_history(EditKind::DeleteNewline, Pos::new(row, 0, 0), prev_line_end);
                return true;
            } else {
                return false;
            }
        }
        let line = &mut self.lines[row];
        if let Some((offset, c)) = line.char_indices().nth(col - 1) {
            line.remove(offset);
            self.cursor.1 -= 1;
            self.push_history(
                EditKind::DeleteChar(c),
                Pos::new(row, col, offset + c.len_utf8()),
                offset,
            );
            true
        } else {
            false
        }
    }

    pub fn delete_next_char(&mut self) -> bool {
        if self.delete_selection(false) {
            return true;
        }
        let before = self.cursor;
        self.move_cursor_with_shift(CursorMove::Forward, false);
        if before == self.cursor {
            return false;
        }
        self.delete_char()
    }

    pub fn delete_line_by_end(&mut self) -> bool {
        if self.delete_selection(false) {
            return true;
        }
        if self.delete_piece(self.cursor.1, usize::MAX) {
            return true;
        }
        self.delete_next_char()
    }

    pub fn delete_line_by_head(&mut self) -> bool {
        if self.delete_selection(false) {
            return true;
        }
        if self.delete_piece(0, self.cursor.1) {
            return true;
        }
        self.delete_char()
    }

    fn delete_piece(&mut self, col: usize, chars: usize) -> bool {
        if chars == 0 {
            return false;
        }
        let (row, _) = self.cursor;
        let line = &mut self.lines[row];
        if let Some((i, _)) = line.char_indices().nth(col) {
            let bytes = line[i..]
                .char_indices()
                .nth(chars)
                .map(|(i, _)| i)
                .unwrap_or(line[i..].len());
            let removed = line[i..i + bytes].to_string();
            line.replace_range(i..i + bytes, "");
            self.cursor = (row, col);
            self.push_history(
                EditKind::DeleteStr(removed.clone()),
                Pos::new(row, col + removed.chars().count(), i + bytes),
                i,
            );
            self.yank = YankText::Piece(removed);
            true
        } else {
            false
        }
    }

    pub fn delete_word(&mut self) -> bool {
        if self.delete_selection(false) {
            return true;
        }
        let (r, c) = self.cursor;
        if let Some(col) = find_word_start_backward(&self.lines[r], c) {
            self.delete_piece(col, c - col)
        } else if c > 0 {
            self.delete_piece(0, c)
        } else {
            self.delete_char()
        }
    }

    pub fn delete_next_word(&mut self) -> bool {
        if self.delete_selection(false) {
            return true;
        }
        let (r, c) = self.cursor;
        let line = &self.lines[r];
        if let Some(col) = find_word_exclusive_end_forward(line, c) {
            self.delete_piece(c, col - c)
        } else {
            let end_col = line.chars().count();
            if c < end_col {
                self.delete_piece(c, end_col - c)
            } else if r + 1 < self.lines.len() {
                self.cursor = (r + 1, 0);
                self.delete_char()
            } else {
                false
            }
        }
    }

    pub fn paste(&mut self) -> bool {
        self.delete_selection(false);
        match self.yank.clone() {
            YankText::Piece(s) => self.insert_piece(s),
            YankText::Chunk(c) => self.insert_chunk(c),
        }
    }

    pub fn copy(&mut self) {
        if let Some((start, end)) = self.take_selection_positions() {
            if start.row == end.row {
                self.yank = YankText::Piece(
                    self.lines[start.row][start.offset..end.offset].to_string(),
                );
                return;
            }
            let mut chunk = vec![self.lines[start.row][start.offset..].to_string()];
            chunk.extend(self.lines[start.row + 1..end.row].iter().cloned());
            chunk.push(self.lines[end.row][..end.offset].to_string());
            self.yank = YankText::Chunk(chunk);
        }
    }

    pub fn cut(&mut self) -> bool {
        self.delete_selection(true)
    }

    fn delete_selection(&mut self, should_yank: bool) -> bool {
        if let Some((s, e)) = self.take_selection_positions() {
            if s == e {
                return false;
            }
            self.delete_range(s, e, should_yank);
            return true;
        }
        false
    }

    pub fn move_cursor_with_shift(&mut self, m: CursorMove, shift: bool) {
        if shift {
            if self.selection_start.is_none() {
                self.start_selection();
            }
        } else {
            self.cancel_selection();
        }
        self.move_cursor(m);
    }

    pub fn move_cursor(&mut self, m: CursorMove) {
        if let Some(cursor) = self.next_cursor(m) {
            self.cursor = cursor;
        }
    }

    fn next_cursor(&self, m: CursorMove) -> Option<(usize, usize)> {
        let (row, col) = self.cursor;
        let lines = &self.lines;
        use CursorMove::*;
        match m {
            Forward => {
                let line = &lines[row];
                if col >= line.chars().count() {
                    if row + 1 < lines.len() {
                        Some((row + 1, 0))
                    } else {
                        None
                    }
                } else {
                    Some((row, col + 1))
                }
            }
            Back => {
                if col == 0 {
                    let row = row.checked_sub(1)?;
                    Some((row, lines[row].chars().count()))
                } else {
                    Some((row, col - 1))
                }
            }
            Up => {
                let row = row.checked_sub(1)?;
                Some((row, fit_col(col, &lines[row])))
            }
            Down => Some((row + 1, fit_col(col, lines.get(row + 1)?))),
            Head => Some((row, 0)),
            End => Some((row, lines[row].chars().count())),
            Top => Some((0, fit_col(col, &lines[0]))),
            Bottom => {
                let row = lines.len() - 1;
                Some((row, fit_col(col, &lines[row])))
            }
            WordEnd => {
                let line = &lines[row];
                if let Some(c) = find_word_inclusive_end_forward(line, col + 1) {
                    Some((row, c))
                } else {
                    let mut r = row + 1;
                    while r < lines.len() {
                        if let Some(c) = find_word_inclusive_end_forward(&lines[r], 0) {
                            return Some((r, c));
                        }
                        r += 1;
                    }
                    Some((lines.len() - 1, lines[lines.len() - 1].chars().count()))
                }
            }
            WordForward => {
                if let Some(c) = find_word_start_forward(&lines[row], col) {
                    Some((row, c))
                } else if row + 1 < lines.len() {
                    Some((row + 1, 0))
                } else {
                    Some((row, lines[row].chars().count()))
                }
            }
            WordBack => {
                if let Some(c) = find_word_start_backward(&lines[row], col) {
                    Some((row, c))
                } else if row > 0 {
                    Some((row - 1, lines[row - 1].chars().count()))
                } else {
                    Some((row, 0))
                }
            }
            ParagraphForward => {
                let mut prev_is_empty = is_blank(&lines[row]);
                for (row, line) in lines.iter().enumerate().skip(row + 1) {
                    let is_empty = is_blank(line);
                    if !is_empty && prev_is_empty {
                        return Some((row, fit_col(col, line)));
                    }
                    prev_is_empty = is_empty;
                }
                let row = lines.len() - 1;
                Some((row, fit_col(col, &lines[row])))
            }
            ParagraphBack => {
                let row = row.checked_sub(1)?;
                let mut prev_is_empty = is_blank(&lines[row]);
                for row in (0..row).rev() {
                    let is_empty = is_blank(&lines[row]);
                    if is_empty && !prev_is_empty {
                        return Some((row + 1, fit_col(col, &lines[row + 1])));
                    }
                    prev_is_empty = is_empty;
                }
                Some((0, fit_col(col, &lines[0])))
            }
            Jump(row, col) => {
                let row = std::cmp::min(row as usize, lines.len() - 1);
                let col = fit_col(col as usize, &lines[row]);
                Some((row, col))
            }
            InViewport => {
                let (top_row, top_col, width, height) = self.viewport.get();
                let (top_row, top_col) = (top_row as usize, top_col as usize);
                let bottom_row = top_row + (height as usize).max(1) - 1;
                let right_col = top_col + (width as usize).max(1) - 1;
                let mut row = row.clamp(top_row, bottom_row);
                row = std::cmp::min(row, lines.len() - 1);
                let col = col.clamp(top_col, right_col);
                Some((row, fit_col(col, &lines[row])))
            }
        }
    }

    pub fn undo(&mut self) -> bool {
        if let Some(cursor) = self.history.undo(&mut self.lines) {
            self.cancel_selection();
            self.cursor = cursor;
            true
        } else {
            false
        }
    }

    pub fn redo(&mut self) -> bool {
        if let Some(cursor) = self.history.redo(&mut self.lines) {
            self.cancel_selection();
            self.cursor = cursor;
            true
        } else {
            false
        }
    }

    pub fn scroll(&mut self, scrolling: Scrolling) {
        let (rows, cols) = match scrolling {
            Scrolling::Delta { rows, cols } => (rows, cols),
            Scrolling::PageDown => {
                let (_, h) = self.viewport_size();
                (h as i16, 0)
            }
            Scrolling::PageUp => {
                let (_, h) = self.viewport_size();
                (-(h as i16), 0)
            }
            Scrolling::HalfPageDown => {
                let (_, h) = self.viewport_size();
                ((h as i16) / 2, 0)
            }
            Scrolling::HalfPageUp => {
                let (_, h) = self.viewport_size();
                (-(h as i16) / 2, 0)
            }
        };
        let (top_row, top_col, w, h) = self.viewport.get();
        let max_row = self.lines.len().saturating_sub(1) as i32;
        let new_row = (top_row as i32 + rows as i32).clamp(0, max_row.max(0)) as u16;
        let new_col = (top_col as i32 + cols as i32).max(0) as u16;
        self.viewport.set((new_row, new_col, w, h));
        self.move_cursor(CursorMove::InViewport);
    }

    /// Process input with the default (emacs-like) key bindings. Returns true if modified.
    pub fn input(&mut self, key: KeyEvent) -> bool {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let alt = key.modifiers.contains(KeyModifiers::ALT);
        let shift = key.modifiers.contains(KeyModifiers::SHIFT);
        use KeyCode as K;
        match key.code {
            K::Char('m') if ctrl && !alt => {
                self.insert_newline();
                true
            }
            K::Char('\n') | K::Char('\r') if !ctrl && !alt => {
                self.insert_newline();
                true
            }
            K::Enter => {
                self.insert_newline();
                true
            }
            K::Char(c) if !ctrl && !alt => {
                self.insert_char(c);
                true
            }
            K::Tab if !ctrl && !alt => self.insert_tab(),
            K::Char('h') if ctrl && !alt => self.delete_char(),
            K::Backspace if !ctrl && !alt => self.delete_char(),
            K::Char('d') if ctrl && !alt => self.delete_next_char(),
            K::Delete if !ctrl && !alt => self.delete_next_char(),
            K::Char('k') if ctrl && !alt => self.delete_line_by_end(),
            K::Char('j') if ctrl && !alt => self.delete_line_by_head(),
            K::Char('w') if ctrl && !alt => self.delete_word(),
            K::Char('h') if !ctrl && alt => self.delete_word(),
            K::Backspace if !ctrl && alt => self.delete_word(),
            K::Delete if !ctrl && alt => self.delete_next_word(),
            K::Char('d') if !ctrl && alt => self.delete_next_word(),
            K::Char('n') if ctrl && !alt => {
                self.move_cursor_with_shift(CursorMove::Down, shift);
                false
            }
            K::Down if !ctrl && !alt => {
                self.move_cursor_with_shift(CursorMove::Down, shift);
                false
            }
            K::Char('p') if ctrl && !alt => {
                self.move_cursor_with_shift(CursorMove::Up, shift);
                false
            }
            K::Up if !ctrl && !alt => {
                self.move_cursor_with_shift(CursorMove::Up, shift);
                false
            }
            K::Char('f') if ctrl && !alt => {
                self.move_cursor_with_shift(CursorMove::Forward, shift);
                false
            }
            K::Right if !ctrl && !alt => {
                self.move_cursor_with_shift(CursorMove::Forward, shift);
                false
            }
            K::Char('b') if ctrl && !alt => {
                self.move_cursor_with_shift(CursorMove::Back, shift);
                false
            }
            K::Left if !ctrl && !alt => {
                self.move_cursor_with_shift(CursorMove::Back, shift);
                false
            }
            K::Char('a') if ctrl && !alt => {
                self.move_cursor_with_shift(CursorMove::Head, shift);
                false
            }
            K::Home => {
                self.move_cursor_with_shift(CursorMove::Head, shift);
                false
            }
            K::Left | K::Char('b') if ctrl && alt => {
                self.move_cursor_with_shift(CursorMove::Head, shift);
                false
            }
            K::Char('e') if ctrl && !alt => {
                self.move_cursor_with_shift(CursorMove::End, shift);
                false
            }
            K::End => {
                self.move_cursor_with_shift(CursorMove::End, shift);
                false
            }
            K::Right | K::Char('f') if ctrl && alt => {
                self.move_cursor_with_shift(CursorMove::End, shift);
                false
            }
            K::Char('<') if !ctrl && alt => {
                self.move_cursor_with_shift(CursorMove::Top, shift);
                false
            }
            K::Up | K::Char('p') if ctrl && alt => {
                self.move_cursor_with_shift(CursorMove::Top, shift);
                false
            }
            K::Char('>') if !ctrl && alt => {
                self.move_cursor_with_shift(CursorMove::Bottom, shift);
                false
            }
            K::Down | K::Char('n') if ctrl && alt => {
                self.move_cursor_with_shift(CursorMove::Bottom, shift);
                false
            }
            K::Char('f') if !ctrl && alt => {
                self.move_cursor_with_shift(CursorMove::WordForward, shift);
                false
            }
            K::Right if ctrl && !alt => {
                self.move_cursor_with_shift(CursorMove::WordForward, shift);
                false
            }
            K::Char('b') if !ctrl && alt => {
                self.move_cursor_with_shift(CursorMove::WordBack, shift);
                false
            }
            K::Left if ctrl && !alt => {
                self.move_cursor_with_shift(CursorMove::WordBack, shift);
                false
            }
            K::Char(']') | K::Char('n') if !ctrl && alt => {
                self.move_cursor_with_shift(CursorMove::ParagraphForward, shift);
                false
            }
            K::Down if ctrl && !alt => {
                self.move_cursor_with_shift(CursorMove::ParagraphForward, shift);
                false
            }
            K::Char('[') | K::Char('p') if !ctrl && alt => {
                self.move_cursor_with_shift(CursorMove::ParagraphBack, shift);
                false
            }
            K::Up if ctrl && !alt => {
                self.move_cursor_with_shift(CursorMove::ParagraphBack, shift);
                false
            }
            K::Char('u') if ctrl && !alt => self.undo(),
            K::Char('r') if ctrl && !alt => self.redo(),
            K::Char('y') if ctrl && !alt => self.paste(),
            K::Char('x') if ctrl && !alt => self.cut(),
            K::Char('c') if ctrl && !alt => {
                self.copy();
                false
            }
            K::Char('v') if ctrl && !alt => {
                self.scroll(Scrolling::PageDown);
                false
            }
            K::PageDown => {
                self.scroll(Scrolling::PageDown);
                false
            }
            K::Char('v') if !ctrl && alt => {
                self.scroll(Scrolling::PageUp);
                false
            }
            K::PageUp => {
                self.scroll(Scrolling::PageUp);
                false
            }
            _ => false,
        }
    }

    fn build_display(&self, s: &str) -> String {
        if !s.contains('\t') {
            return s.to_string();
        }
        let mut out = String::new();
        let mut width = 0usize;
        for c in s.chars() {
            if c == '\t' {
                let len = self.tab_len as usize - (width % self.tab_len as usize);
                out.push_str(&" ".repeat(len));
                width += len;
            } else {
                out.push(c);
                width += unicode_width::UnicodeWidthChar::width(c).unwrap_or(0);
            }
        }
        out
    }

    fn line_spans(&self, row: usize) -> Line<'static> {
        let line = &self.lines[row];
        let mut boundaries: Vec<(BoundaryKind, Style, usize)> = Vec::new();
        let mut style_begin = Style::default();
        let mut cursor_at_end = false;
        let mut select_at_end = false;
        if row == self.cursor.0 {
            if let Some((start, c)) = line.char_indices().nth(self.cursor.1) {
                boundaries.push((BoundaryKind::Cursor, self.cursor_style, start));
                boundaries.push((BoundaryKind::End, Style::default(), start + c.len_utf8()));
            } else {
                cursor_at_end = true;
            }
            style_begin = self.cursor_line_style;
        }
        if let Some((s, e)) = self.selection_positions() {
            let range = if row == s.row {
                if s.row == e.row {
                    Some((s.offset, e.offset))
                } else {
                    select_at_end = true;
                    Some((s.offset, line.len()))
                }
            } else if row == e.row {
                Some((0, e.offset))
            } else if s.row < row && row < e.row {
                select_at_end = true;
                Some((0, line.len()))
            } else {
                None
            };
            if let Some((start, end)) = range {
                if start != end {
                    boundaries.push((BoundaryKind::Select, self.select_style, start));
                    boundaries.push((BoundaryKind::End, Style::default(), end));
                }
            }
        }
        let mut spans: Vec<Span<'static>> = Vec::new();
        if boundaries.is_empty() {
            let built = self.build_display(line);
            if !built.is_empty() {
                spans.push(Span::styled(built, style_begin));
            }
        } else {
            boundaries.sort_by(|(lk, _, i), (rk, _, j)| match i.cmp(j) {
                Ordering::Equal => lk.cmp(rk),
                o => o,
            });
            let mut style = style_begin;
            let mut start = 0;
            let mut stack: Vec<Style> = vec![];
            for (kind, bstyle, end) in boundaries {
                if start < end {
                    spans.push(Span::styled(self.build_display(&line[start..end]), style));
                }
                style = if kind != BoundaryKind::End {
                    stack.push(style);
                    bstyle
                } else {
                    stack.pop().unwrap_or(style_begin)
                };
                start = end;
            }
            if start != line.len() {
                spans.push(Span::styled(self.build_display(&line[start..]), style));
            }
        }
        if cursor_at_end {
            spans.push(Span::styled(" ", self.cursor_style));
        } else if select_at_end {
            spans.push(Span::styled(" ", self.select_style));
        }
        Line::from(spans)
    }

    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        let inner = match &self.block {
            Some(b) => b.inner(area),
            None => area,
        };
        let (width, height) = (inner.width, inner.height);
        let (prev_top_row, prev_top_col, _, _) = self.viewport.get();
        let top_row = next_scroll_top(prev_top_row, self.cursor.0 as u16, height);
        let top_col = next_scroll_top(prev_top_col, self.cursor.1 as u16, width);
        let (text, style) = if !self.placeholder.is_empty() && self.is_empty() {
            (
                vec![Line::from(Span::raw(self.placeholder.clone()))],
                self.placeholder_style,
            )
        } else {
            let end = std::cmp::min(top_row as usize + height as usize, self.lines.len());
            let start = std::cmp::min(top_row as usize, end);
            ((start..end).map(|r| self.line_spans(r)).collect(), self.style)
        };
        let mut p = Paragraph::new(text).style(style);
        if let Some(b) = &self.block {
            b.clone().render(area, buf);
        }
        if top_col != 0 {
            p = p.scroll((0, top_col));
        }
        self.viewport.set((top_row, top_col, width, height));
        p.render(inner, buf);
    }
}
