                        let p = unsafe { sqlite3_column_text(stmt, col) };
                        let n = unsafe { sqlite3_column_bytes(stmt, col) };
                        let s = if p.is_null() {
                            String::new()
                        } else {
                            let slice = unsafe { std::slice::from_raw_parts(p, n as usize) };
                            String::from_utf8_lossy(slice).into_owned()
                        };
                        values.push(Some(RowValue::Text(s)));
                    }
                    col += 1;
                }
                rows.push(Row { values });
            } else if rc == SQLITE_DONE {
                break;
            } else {
                let msg = self.errmsg();
                unsafe { sqlite3_finalize(stmt) };
                anyhow::bail!("error returned from database: (code: {rc}) {msg}");
            }
        }
        unsafe { sqlite3_finalize(stmt) };
        Ok(rows)
    }

    pub fn last_insert_rowid(&self) -> i64 {
        unsafe { sqlite3_last_insert_rowid(self.db) }
    }
}

impl Drop for Connection {
    fn drop(&mut self) {
        if !self.db.is_null() {
            unsafe { sqlite3_close(self.db) };
        }
    }
}
