use std::collections::{BTreeSet, HashSet};
use std::path::PathBuf;

use anyhow::Context;
use serde::{Deserialize, Serialize};

use crate::backend::Backend;
use crate::entry::{EntriesDTO, Entry, EntryDraft, TRANSFER_DATA_VERSION};
use crate::settings::Settings;
use crate::theme::Styles;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum SortCriteria {
    Date,
    Priority,
    Title,
}

impl SortCriteria {
    pub fn name(&self) -> &'static str {
        match self {
            SortCriteria::Date => "Date",
            SortCriteria::Priority => "Priority",
            SortCriteria::Title => "Title",
        }
    }
    pub fn all() -> [SortCriteria; 3] {
        [SortCriteria::Date, SortCriteria::Priority, SortCriteria::Title]
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum SortOrder {
    Ascending,
    Descending,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Sorter {
    pub criteria: Vec<SortCriteria>,
    pub order: SortOrder,
}

impl Default for Sorter {
    fn default() -> Self {
        Self {
            criteria: vec![SortCriteria::Date, SortCriteria::Priority],
            order: SortOrder::Descending,
        }
    }
}

impl Sorter {
    pub fn compare(&self, a: &Entry, b: &Entry) -> std::cmp::Ordering {
        use std::cmp::Ordering;
        let mut res = Ordering::Equal;
        for c in &self.criteria {
            res = match c {
                SortCriteria::Date => a.date.cmp(&b.date),
                SortCriteria::Priority => a.priority.cmp(&b.priority),
                SortCriteria::Title => a.title.cmp(&b.title),
            };
            if res != Ordering::Equal {
                break;
            }
        }
        match self.order {
            SortOrder::Ascending => res,
            SortOrder::Descending => res.reverse(),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AppState {
    #[serde(default)]
    pub sorter: Sorter,
    #[serde(default)]
    pub full_screen: bool,
}

impl Default for AppState {
    fn default() -> Self {
        Self {
            sorter: Sorter::default(),
            full_screen: false,
        }
    }
}

const STATE_FILE: &str = "state.json";

impl AppState {
    pub fn load(dir: &PathBuf) -> anyhow::Result<AppState> {
        let path = dir.join(STATE_FILE);
        if !path.exists() {
            let state = AppState::default();
            state.save(dir)?;
            return Ok(state);
        }
        let text = std::fs::read_to_string(&path)?;
        let state: AppState = serde_json::from_str(&text)
            .with_context(|| format!("Error while parsing app state file. Path: {}", path.display()))?;
        Ok(state)
    }

    pub fn save(&self, dir: &PathBuf) -> anyhow::Result<()> {
        std::fs::create_dir_all(dir)?;
        let path = dir.join(STATE_FILE);
        let text = serde_json::to_string_pretty(self)?;
        std::fs::write(path, text)?;
        Ok(())
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CriteriaRelation {
    And,
    Or,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FilterCriterion {
    Tag(String),
    Title(String),
    Content(String),
    Priority(u32),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Filter {
    pub relation: CriteriaRelation,
    pub criteria: Vec<FilterCriterion>,
}

impl Filter {
    pub fn check_entry(&self, entry: &Entry) -> bool {
        let check = |c: &FilterCriterion| match c {
            FilterCriterion::Tag(tag) => entry.tags.contains(tag),
            FilterCriterion::Title(t) => {
                entry.title.to_lowercase().contains(&t.to_lowercase())
            }
            FilterCriterion::Content(t) => {
                entry.content.to_lowercase().contains(&t.to_lowercase())
            }
            FilterCriterion::Priority(p) => entry.priority == Some(*p),
        };
        match self.relation {
            CriteriaRelation::And => self.criteria.iter().all(check),
            CriteriaRelation::Or => self.criteria.iter().any(check),
        }
    }
}

/// A change which can be undone/redone
#[derive(Debug, Clone)]
pub enum Change {
    AddEntry { id: u32 },
    RemoveEntry(Box<Entry>),
    EntryAttribute(Box<Entry>),
    EntryContent { id: u32, content: String },
}

pub struct App {
    pub settings: Settings,
    pub styles: Styles,
    pub backend: Backend,
    pub entries: Vec<Entry>,
    pub current_entry_id: Option<u32>,
    pub filter: Option<Filter>,
    pub fuzzy_filter: Option<String>,
    pub state: AppState,
    pub selected_entries: HashSet<u32>,
    pub undo_stack: Vec<Change>,
    pub redo_stack: Vec<Change>,
}

impl App {
    pub fn new(settings: Settings, styles: Styles, backend: Backend, state: AppState) -> Self {
        Self {
            settings,
            styles,
            backend,
            entries: Vec::new(),
            current_entry_id: None,
            filter: None,
            fuzzy_filter: None,
            state,
            selected_entries: HashSet::new(),
            undo_stack: Vec::new(),
            redo_stack: Vec::new(),
        }
    }

    pub fn load_entries(&mut self) -> anyhow::Result<()> {
        self.entries = self.backend.load_all_entries()?;
        Ok(())
    }

    /// Entries after applying filter and sorting
    pub fn active_entries(&self) -> Vec<&Entry> {
        let mut v: Vec<&Entry> = self
            .entries
            .iter()
            .filter(|e| self.filter.as_ref().map(|f| f.check_entry(e)).unwrap_or(true))
            .collect();
        v.sort_by(|a, b| self.state.sorter.compare(a, b));
        v
    }

    pub fn get_entry(&self, id: u32) -> Option<&Entry> {
        self.entries.iter().find(|e| e.id == id)
    }

    pub fn current_entry(&self) -> Option<&Entry> {
        self.current_entry_id.and_then(|id| self.get_entry(id))
    }

    pub fn all_tags(&self) -> Vec<String> {
        let set: BTreeSet<&String> = self.entries.iter().flat_map(|e| e.tags.iter()).collect();
        set.into_iter().cloned().collect()
    }

    pub fn push_undo(&mut self, change: Change) {
        self.undo_stack.push(change);
        let limit = self.settings.history_limit;
        if self.undo_stack.len() > limit {
            let excess = self.undo_stack.len() - limit;
            self.undo_stack.drain(0..excess);
        }
        self.redo_stack.clear();
    }

    pub fn add_entry(&mut self, draft: EntryDraft) -> anyhow::Result<u32> {
        let entry = self.backend.add_entry(draft)?;
        let id = entry.id;
        self.entries.push(entry);
        Ok(id)
    }

    pub fn delete_entry(&mut self, id: u32) -> anyhow::Result<Option<Entry>> {
        self.backend.remove_entry(id)?;
        let removed = match self.entries.iter().position(|e| e.id == id) {
            Some(pos) => Some(self.entries.remove(pos)),
            None => None,
        };
        self.selected_entries.remove(&id);
        Ok(removed)
    }

    pub fn update_entry(&mut self, entry: Entry) -> anyhow::Result<()> {
        let updated = self.backend.update_entry(entry)?;
        if let Some(e) = self.entries.iter_mut().find(|e| e.id == updated.id) {
            *e = updated;
        }
        Ok(())
    }

    pub fn export_entries(&self, path: &PathBuf, ids: &[u32]) -> anyhow::Result<()> {
        let mut entries: Vec<&Entry> = self.entries.iter().filter(|e| ids.contains(&e.id)).collect();
        entries.sort_by_key(|e| e.id);
        let dto = EntriesDTO {
            version: TRANSFER_DATA_VERSION,
            entries: entries.into_iter().map(EntryDraft::from_entry).collect(),
        };
        if let Some(parent) = path.parent() {
            if !parent.as_os_str().is_empty() {
                std::fs::create_dir_all(parent)?;
            }
        }
        let text = serde_json::to_string_pretty(&dto)?;
        std::fs::write(path, text)?;
        Ok(())
    }

    pub fn import_entries(&mut self, path: &PathBuf) -> anyhow::Result<()> {
        if !path.exists() {
            anyhow::bail!("Import file doesn't exist: path {}", path.display());
        }
        let text = std::fs::read_to_string(path)
            .map_err(|err| anyhow::anyhow!("Error while reading import file. Error: {err}"))?;
        let dto: EntriesDTO = serde_json::from_str(&text)
            .map_err(|err| anyhow::anyhow!("Error while parsing import file. Error: {err}"))?;
        self.backend.import_entries(dto.entries)?;
        self.load_entries()?;
        Ok(())
    }

    pub fn assign_priority(&mut self, priority: u32) -> anyhow::Result<()> {
        self.backend.assign_priority_to_entries(priority)?;
        self.load_entries()?;
        Ok(())
    }

    pub fn save_state(&self) -> anyhow::Result<()> {
        self.state.save(&self.settings.app_state_dir)
    }
}
EOF
echo ok"}

