use ratatui::layout::{Constraint, Layout, Rect};

/// Rect centered with the given percentages of the area
pub fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let vertical = Layout::vertical([
        Constraint::Percentage((100 - percent_y) / 2),
        Constraint::Percentage(percent_y),
        Constraint::Percentage((100 - percent_y) / 2),
    ])
    .split(r);
    Layout::horizontal([
        Constraint::Percentage((100 - percent_x) / 2),
        Constraint::Percentage(percent_x),
        Constraint::Percentage((100 - percent_x) / 2),
    ])
    .split(vertical[1])[1]
}

/// Rect with a given exact height, centered vertically with percentages
pub fn centered_rect_exact_height(percent_x: u16, height: u16, r: Rect) -> Rect {
    let percent_y = if r.height == 0 {
        100
    } else {
        (height as u32 * 100 / r.height as u32) as u16
    };
    let half = 100u16.wrapping_sub(percent_y) / 2;
    let vertical = Layout::vertical([
        Constraint::Percentage(half),
        Constraint::Length(height),
        Constraint::Percentage(half),
    ])
    .split(r);
    Layout::horizontal([
        Constraint::Percentage((100 - percent_x) / 2),
        Constraint::Percentage(percent_x),
        Constraint::Percentage((100 - percent_x) / 2),
    ])
    .split(vertical[1])[1]
}
