use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use ratatui::layout::{Alignment, Constraint, Layout, Margin, Rect};
use ratatui::style::Style;
use ratatui::text::{Line, Text};
use ratatui::widgets::{Block, Borders, Clear, Paragraph, Wrap};
use ratatui::Frame;

use super::layout::centered_rect_exact_height;
use crate::theme::Styles;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MsgBoxType {
    Error,
    Warning,
    Info,
    Question,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MsgBoxActions {
    Ok,
    OkCancel,
    YesNo,
    YesNoCancel,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MsgBoxResult {
    Ok,
    Cancel,
    Yes,
    No,
}

#[derive(Debug, Clone)]
pub struct MsgBox {
    pub msg_type: MsgBoxType,
    pub actions: MsgBoxActions,
    pub text: String,
}

impl MsgBox {
    pub fn new(msg_type: MsgBoxType, actions: MsgBoxActions, text: String) -> Self {
        Self {
            msg_type,
            actions,
            text,
        }
    }

    pub fn error(text: String) -> Self {
        Self::new(MsgBoxType::Error, MsgBoxActions::Ok, text)
    }

    pub fn info(text: String) -> Self {
        Self::new(MsgBoxType::Info, MsgBoxActions::Ok, text)
    }

    pub fn render(&self, f: &mut Frame, styles: &Styles) {
        let area = centered_rect_exact_height(55, 8, f.area());
        let color = match self.msg_type {
            MsgBoxType::Error => styles.msgbox.error,
            MsgBoxType::Warning => styles.msgbox.warning,
            MsgBoxType::Info => styles.msgbox.info,
            MsgBoxType::Question => styles.msgbox.question,
        };
        let title = match self.msg_type {
            MsgBoxType::Error => "Error",
            MsgBoxType::Warning => "Warning",
            MsgBoxType::Info => "Info",
            MsgBoxType::Question => "",
        };
        let block = Block::default()
            .borders(Borders::ALL)
            .title(title)
            .style(Style::default().fg(color));
        f.render_widget(Clear, area);
        let inner = block.inner(area);
        f.render_widget(block, area);
        let inner = inner.inner(Margin::new(2, 1));
        let chunks = Layout::vertical([Constraint::Min(1), Constraint::Length(1)]).split(inner);
        let text = Paragraph::new(Text::from(self.text.as_str()))
            .alignment(Alignment::Center)
            .wrap(Wrap { trim: false });
