use chrono::{Datelike, NaiveDate, TimeZone, Utc};
use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use ratatui::layout::{Alignment, Constraint, Layout, Margin};
use ratatui::style::Style;
use ratatui::widgets::{Block, Borders, Clear, Paragraph, Wrap};
use ratatui::Frame;

use super::layout::centered_rect_exact_height;
use super::tags_popup::TagsPopup;
use super::util::paragraph_line_count;
use crate::entry::{Entry, EntryDraft};
use crate::textarea::{CursorMove, TextArea};
use crate::theme::Styles;

const FOOTER_TEXT: &str = "Enter or <Ctrl-m>: confirm | Esc or <Ctrl-c>: Cancel | Tab: Change focused control | <Ctrl-Space> or <Ctrl-t>: Open tags";

pub enum EntryPopupResult {
    None,
    Cancel,
    Create(EntryDraft),
    Update(Entry),
}

pub struct EntryPopup {
    fields: [TextArea; 4],
    errors: [Option<String>; 4],
    active: usize,
    edit_entry: Option<Entry>,
    pub tags_popup: Option<TagsPopup>,
}

impl EntryPopup {
    pub fn new_entry() -> Self {
        let today = chrono::Local::now().date_naive();
        let date = format!("{:02}-{:02}-{}", today.day(), today.month(), today.year());
        Self {
            fields: [
                TextArea::default(),
                TextArea::new(vec![date]),
                TextArea::default(),
                TextArea::default(),
            ],
            errors: [None, None, None, None],
            active: 0,
            edit_entry: None,
            tags_popup: None,
        }
    }

    pub fn edit_entry(entry: &Entry) -> Self {
        let date = format!(
            "{:02}-{:02}-{}",
            entry.date.day(),
            entry.date.month(),
            entry.date.year()
        );
        let priority = entry.priority.map(|p| p.to_string()).unwrap_or_default();
        let tags = entry.tags.join(", ");
        Self {
            fields: [
                TextArea::new(vec![entry.title.clone()]),
                TextArea::new(vec![date]),
                TextArea::new(vec![priority]),
                TextArea::new(vec![tags]),
            ],
            errors: [None, None, None, None],
            active: 0,
            edit_entry: Some(entry.clone()),
            tags_popup: None,
        }
    }

    fn field_text(&self, i: usize) -> String {
        self.fields[i].lines().first().cloned().unwrap_or_default()
    }

    fn validate(&mut self, i: usize) {
        let text = self.field_text(i);
        self.errors[i] = match i {
            0 => {
                if text.is_empty() {
                    Some("Title can't be empty".to_string())
                } else {
                    None
                }
            }
            1 => match NaiveDate::parse_from_str(&text, "%d-%m-%Y") {
                Ok(_) => None,
                Err(e) => Some(e.to_string()),
            },
            2 => {
                if text.is_empty() {
                    None
                } else {
                    match text.parse::<u32>() {
                        Ok(_) => None,
                        Err(_) => Some("Priority must be a positive number".to_string()),
                    }
                }
            }
            _ => None,
        };
    }

    fn parse_tags(text: &str) -> Vec<String> {
        if text.is_empty() {
            return Vec::new();
        }
        text.split(',').map(|t| t.trim().to_string()).collect()
    }

    pub fn render(&mut self, f: &mut Frame, styles: &Styles) {
        let mut area = centered_rect_exact_height(70, 17, f.area());
        let footer_width = area.width.saturating_sub(8);
        let footer_lines = paragraph_line_count(FOOTER_TEXT, footer_width) as u16;
        area.height = 16 + footer_lines;
        let title = if self.edit_entry.is_some() {
            "Edit journal"
        } else {
            "Create journal"
        };
        let block = Block::default().borders(Borders::ALL).title(title);
        f.render_widget(Clear, area);
        let inner = block.inner(area).inner(Margin::new(3, 1));
        f.render_widget(block, area);
        let chunks = Layout::vertical([
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Min(1),
        ])
        .split(inner);
        let names = ["Title", "Date", "Priority", "Tags"];
        for i in 0..4 {
            let focused = i == self.active && self.tags_popup.is_none();
            let invalid = self.errors[i].is_some();
            let mut title = names[i].to_string();
            if let Some(err) = &self.errors[i] {
                title = format!("{} : {}", names[i], err);
            } else if i == 3 && focused {
                title = "Tags - A comma-separated list".to_string();
            }
            let style: Style = if invalid {
                styles.general.input_block_invalid.into()
            } else if focused {
                styles.general.input_block_active.into()
            } else {
                Style::default()
            };
            let cursor_style: Style = if focused {
                if invalid {
                    styles.general.input_corsur_invalid.into()
                } else {
                    styles.general.input_corsur_active.into()
                }
            } else {
                Style::default()
            };
            let ta = &mut self.fields[i];
            ta.set_cursor_line_style(Style::default());
            ta.set_cursor_style(cursor_style);
            ta.set_style(style);
            ta.set_block(Block::default().borders(Borders::ALL).title(title).style(style));
            ta.render(chunks[i], f.buffer_mut());
        }
        let footer = Paragraph::new(FOOTER_TEXT)
            .alignment(Alignment::Center)
            .wrap(Wrap { trim: false });
        f.render_widget(footer, chunks[4]);

        if let Some(tags) = &mut self.tags_popup {
            tags.render(f, styles);
        }
    }

    pub fn handle_key(&mut self, key: &KeyEvent, all_tags: &[String]) -> EntryPopupResult {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        if let Some(tags) = &mut self.tags_popup {
            match tags.handle_key(key) {
                super::tags_popup::TagsResult::None => {}
                super::tags_popup::TagsResult::Cancel => {
                    self.tags_popup = None;
                }
                super::tags_popup::TagsResult::Apply(selected) => {
                    let text = selected.join(", ");
                    let mut ta = TextArea::new(vec![text]);
                    ta.move_cursor(CursorMove::End);
                    self.fields[3] = ta;
                    self.tags_popup = None;
                }
            }
            return EntryPopupResult::None;
        }
        match key.code {
            KeyCode::Enter => return self.confirm(),
            KeyCode::Char('m') if ctrl => return self.confirm(),
            KeyCode::Esc => return EntryPopupResult::Cancel,
            KeyCode::Char('c') if ctrl => return EntryPopupResult::Cancel,
            KeyCode::Tab if key.modifiers.is_empty() => {
                self.active = (self.active + 1) % 4;
                return EntryPopupResult::None;
            }
            KeyCode::Char(' ') | KeyCode::Char('t') if ctrl => {
                let current = Self::parse_tags(&self.field_text(3));
                self.tags_popup = Some(TagsPopup::new(all_tags, &current));
                return EntryPopupResult::None;
            }
            _ => {}
        }
        let modified = self.fields[self.active].input(*key);
        if modified {
            self.validate(self.active);
        }
        EntryPopupResult::None
    }

    fn confirm(&mut self) -> EntryPopupResult {
        for i in 0..4 {
            self.validate(i);
        }
        if self.errors.iter().any(|e| e.is_some()) {
            return EntryPopupResult::None;
        }
        let title = self.field_text(0);
        let date = NaiveDate::parse_from_str(&self.field_text(1), "%d-%m-%Y").unwrap();
        let date = Utc.from_utc_datetime(&date.and_hms_opt(0, 0, 0).unwrap());
        let priority_text = self.field_text(2);
        let priority = if priority_text.is_empty() {
            None
        } else {
            priority_text.parse::<u32>().ok()
        };
        let tags = Self::parse_tags(&self.field_text(3));
        match &self.edit_entry {
            Some(entry) => {
                let mut e = entry.clone();
                e.title = title;
                e.date = date;
                e.priority = priority;
                e.tags = tags;
                EntryPopupResult::Update(e)
            }
            None => EntryPopupResult::Create(EntryDraft {
                date,
                title,
                content: String::new(),
                tags,
                priority,
            }),
        }
    }
}
EOF
echo ok"}

