                self.active = (self.active + 1) % 4;
                return EntryPopupResult::None;
            }
            KeyCode::Char(' ') | KeyCode::Char('t') if ctrl => {
                let current = Self::parse_tags(&self.field_text(3));
                self.tags_popup = Some(TagsPopup::new(all_tags, &current));
                return EntryPopupResult::None;
            }
            _ => {}
        }
        let modified = self.fields[self.active].input(*key);
        if modified {
            self.validate(self.active);
        }
        EntryPopupResult::None
    }

    fn confirm(&mut self) -> EntryPopupResult {
        for i in 0..4 {
            self.validate(i);
        }
        if self.errors.iter().any(|e| e.is_some()) {
            return EntryPopupResult::None;
        }
        let title = self.field_text(0);
        let date = NaiveDate::parse_from_str(&self.field_text(1), "%d-%m-%Y").unwrap();
        let date = Utc.from_utc_datetime(&date.and_hms_opt(0, 0, 0).unwrap());
        let priority_text = self.field_text(2);
        let priority = if priority_text.is_empty() {
            None
        } else {
            priority_text.parse::<u32>().ok()
        };
        let tags = Self::parse_tags(&self.field_text(3));
        match &self.edit_entry {
            Some(entry) => {
                let mut e = entry.clone();
                e.title = title;
                e.date = date;
                e.priority = priority;
                e.tags = tags;
                EntryPopupResult::Update(e)
            }
            None => EntryPopupResult::Create(EntryDraft {
                date,
                title,
                content: String::new(),
                tags,
                priority,
            }),
        }
    }
}
