use super::layout::centered_rect;
use super::util::paragraph_line_count;
use crate::theme::Styles;

const FOOTER_TEXT: &str =
    "<Space>: Toggle Selected | Enter or <Ctrl-m>: Confirm | Esc, q or <Ctrl-c>: Cancel";

pub enum TagsResult {
    None,
    Cancel,
    Apply(Vec<String>),
}

pub struct TagsPopup {
    tags: Vec<String>,
    selected: Vec<String>,
    state: ListState,
    pub parent_area: Rect,
}

impl TagsPopup {
    pub fn new(all_tags: &[String], current: &[String]) -> Self {
        let mut tags: Vec<String> = Vec::new();
        for t in current {
            if !all_tags.contains(t) && !tags.contains(t) {
                tags.push(t.clone());
            }
        }
        tags.extend(all_tags.iter().cloned());
        let mut state = ListState::default();
        if !tags.is_empty() {
            state.select(Some(0));
        }
        Self {
            tags,
            selected: current.to_vec(),
            state,
            parent_area: Rect::default(),
        }
    }

    pub fn render(&mut self, f: &mut Frame, styles: &Styles) {
        let area = centered_rect(70, 90, self.parent_area);
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title("Tags");
        f.render_widget(Clear, area);
        let inner = block.inner(area);
        f.render_widget(block, area);
        let footer_lines = paragraph_line_count(FOOTER_TEXT, inner.width) as u16;
        let chunks =
            Layout::vertical([Constraint::Min(1), Constraint::Length(footer_lines + 1)]).split(inner);
        if self.tags.is_empty() {
            let p = Paragraph::new(Text::from(vec![
                Line::default(),
                Line::from("No journals with tags provided"),
            ]))
            .alignment(Alignment::Center)
            .wrap(Wrap { trim: false });
            f.render_widget(p, chunks[0]);
        } else {
            let selected_style: Style = styles.general.list_item_selected.into();
            let items: Vec<ListItem> = self
                .tags
                .iter()
                .map(|t| {
                    if self.selected.contains(t) {
                        ListItem::new(format!("* {t}")).style(selected_style)
                    } else {
                        ListItem::new(t.as_str())
                    }
                })
                .collect();
            let list = List::new(items)
                .highlight_symbol(">> ")
                .highlight_style(Style::from(styles.general.list_highlight_active));
            f.render_stateful_widget(list, chunks[0], &mut self.state);
        }
        let footer = Paragraph::new(FOOTER_TEXT)
            .alignment(Alignment::Center)
            .wrap(Wrap { trim: false })
            .block(Block::default().borders(Borders::TOP));
        f.render_widget(footer, chunks[1]);
    }

    pub fn handle_key(&mut self, key: &KeyEvent) -> TagsResult {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let len = self.tags.len();
        match key.code {
            KeyCode::Esc | KeyCode::Char('q') => return TagsResult::Cancel,
            KeyCode::Char('c') if ctrl => return TagsResult::Cancel,
            KeyCode::Enter => return self.apply(),
            KeyCode::Char('m') if ctrl => return self.apply(),
            KeyCode::Char('j') | KeyCode::Down => {
                if len > 0 {
                    let i = match self.state.selected() {
                        Some(i) if i + 1 < len => i + 1,
                        Some(_) => 0,
                        None => 0,
                    };
                    self.state.select(Some(i));
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if len > 0 {
                    let i = match self.state.selected() {
                        Some(0) | None => len - 1,
                        Some(i) => i - 1,
                    };
                    self.state.select(Some(i));
                }
            }
            KeyCode::Char(' ') => {
                if let Some(i) = self.state.selected() {
                    let tag = self.tags[i].clone();
                    if let Some(pos) = self.selected.iter().position(|t| *t == tag) {
                        self.selected.remove(pos);
                    } else {
                        self.selected.push(tag);
                    }
                }
            }
            _ => {}
        }
        TagsResult::None
    }

    fn apply(&self) -> TagsResult {
        let out: Vec<String> = self
            .tags
            .iter()
            .filter(|t| self.selected.contains(t))
            .cloned()
            .collect();
        TagsResult::Apply(out)
    }
}
