impl HelpPopup {
    pub fn new(tab: usize) -> Self {
        Self {
            tab,
            global_state: TableState::default(),
            multi_state: TableState::default(),
        }
    }

    fn rows_count(&self) -> usize {
        match self.tab {
            0 => commands_in_order(&global_bindings()).len(),
            2 => commands_in_order(&multi_select_bindings()).len(),
            _ => 0,
        }
    }

    pub fn render(&mut self, f: &mut Frame) {
        let area = centered_rect(90, 80, f.area());
        f.render_widget(Clear, area);
        let block = Block::default().borders(Borders::ALL).title("Help");
        let inner = block.inner(area);
        f.render_widget(block, area);
        let inner = inner.inner(Margin::new(1, 0));
        let chunks = Layout::vertical([Constraint::Length(3), Constraint::Min(1)]).split(inner);

        let titles = ["Global", "Editor", "Multi-Select"];
        let tab_titles: Vec<Line> = titles
            .iter()
            .map(|t| {
                let (first, rest) = t.split_at(1);
                Line::from(vec![
                    Span::styled(
                        first.to_string(),
                        Style::default().fg(Color::LightGreen).add_modifier(Modifier::BOLD),
                    ),
                    Span::raw(rest.to_string()),
                ])
            })
            .collect();
        let tabs = Tabs::new(tab_titles)
            .block(Block::default().borders(Borders::ALL).title("Tabs"))
            .select(self.tab)
            .highlight_style(Style::default().add_modifier(Modifier::UNDERLINED));
        f.render_widget(tabs, chunks[0]);

        match self.tab {
            0 => {
                let bindings = global_bindings();
                render_table(f, chunks[1], "Global Keybindings", &bindings, &mut self.global_state);
            }
            1 => {
                let p = Paragraph::new(Text::from(EDITOR_HELP))
                    .wrap(Wrap { trim: false })
                    .block(Block::default().borders(Borders::ALL).title("Editor Keybindings"));
                f.render_widget(p, chunks[1]);
            }
            _ => {
                let bindings = multi_select_bindings();
                render_table(
                    f,
                    chunks[1],
                    "Multi-Select Mode Keybindings",
                    &bindings,
                    &mut self.multi_state,
                );
            }
        }
    }

    pub fn handle_key(&mut self, key: &KeyEvent) -> bool {
        // returns true if the popup should be closed
        match key.code {
            KeyCode::Esc | KeyCode::Char('q') => return true,
            KeyCode::Tab | KeyCode::Right | KeyCode::Char('l') => {
                self.tab = (self.tab + 1) % 3;
            }
            KeyCode::BackTab | KeyCode::Left | KeyCode::Char('h') => {
                self.tab = (self.tab + 2) % 3;
            }
            KeyCode::Char('j') | KeyCode::Down => {
                let len = self.rows_count();
                if let Some(state) = self.state_mut() {
                    if len > 0 {
                        let i = match state.selected() {
                            Some(i) if i + 1 < len => i + 1,
                            Some(_) => 0,
                            None => 0,
                        };
                        state.select(Some(i));
                    }
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                let len = self.rows_count();
                if let Some(state) = self.state_mut() {
                    if len > 0 {
                        let i = match state.selected() {
                            Some(0) | None => len - 1,
                            Some(i) => i - 1,
                        };
                        state.select(Some(i));
                    }
                }
            }
            _ => {}
        }
        false
    }

    fn state_mut(&mut self) -> Option<&mut TableState> {
        match self.tab {
            0 => Some(&mut self.global_state),
            2 => Some(&mut self.multi_state),
            _ => None,
        }
    }
}

fn render_table(f: &mut Frame, area: Rect, title: &str, bindings: &[Binding], state: &mut TableState) {
    let block = Block::default().borders(Borders::ALL).title(title.to_string());
    let inner = block.inner(area);
    let widths = [
        Constraint::Percentage(18),
        Constraint::Percentage(28),
        Constraint::Percentage(54),
    ];
    // compute column widths as the table would do
    let cols = Layout::horizontal(widths).spacing(1).split(Rect::new(0, 0, inner.width, 1));
    let key_w = cols[0].width as usize;
    let cmd_w = cols[1].width as usize;
    let desc_w = cols[2].width as usize;

    let cmds = commands_in_order(bindings);
    let rows: Vec<Row> = cmds
        .iter()
        .map(|cmd| {
            let keys: Vec<String> = keys_for(bindings, *cmd).iter().map(|k| k.to_string()).collect();
            let keys_text = keys.join(", ");
            let (name, desc) = cmd.info();
            let k_lines = wrap(&keys_text, key_w.saturating_sub(1).max(1));
            let c_lines = wrap(name, cmd_w.saturating_sub(1).max(1));
            let d_lines = wrap(desc, desc_w.saturating_sub(1).max(1));
            let height = k_lines.len().max(c_lines.len()).max(d_lines.len());
            Row::new(vec![
                Cell::from(Text::from(k_lines.join("\n"))).style(Style::default().add_modifier(Modifier::ITALIC)),
                Cell::from(Text::from(c_lines.join("\n"))),
                Cell::from(Text::from(d_lines.join("\n"))),
            ])
            .height(height as u16)
        })
        .collect();
    let rows_len = rows.len();
    let header = Row::new(vec!["Key", "Command", "Description"])
        .style(Style::default().fg(Color::LightBlue))
        .bottom_margin(1);
    let table = Table::new(rows, widths)
        .header(header)
        .block(block)
        .column_spacing(1);
    f.render_stateful_widget(table, area, state);

    let scrollbar = Scrollbar::new(ScrollbarOrientation::VerticalRight)
        .symbols(symbols::scrollbar::VERTICAL)
        .begin_symbol(Some("▲"))
        .end_symbol(Some("▼"));
    let mut sb_state = ScrollbarState::new(rows_len).position(state.selected().unwrap_or(0));
    f.render_stateful_widget(
        scrollbar,
        area.inner(Margin::new(0, 1)),
        &mut sb_state,
    );
}
