pub const CLIPBOARD_ERROR: &str = "Error while communicating with the operation system clipboard.Error Details: Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ControlType {
