    QuitUnsaved,
    DeleteEntry,
    DeleteSelection,
    /// Save before changing selection: target entry id
    SaveBeforeSwitch,
}

pub enum Popup {
    Help(HelpPopup),
    Entry(EntryPopup),
    MsgBox(MsgBox, MsgBoxPurpose),
}

pub struct UI {
    pub active_control: ControlType,
    pub popups: Vec<Popup>,
    pub list_state: ListState,
    pub editor: Editor,
    pub multi_select: bool,
    pub quit: bool,
}

pub fn run(mut app: App, pending: Option<PendingCliCommand>) -> anyhow::Result<()> {
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;
    terminal.clear()?;

    let res = run_loop(&mut terminal, &mut app, pending);

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    res
}

fn run_loop(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    app: &mut App,
    pending: Option<PendingCliCommand>,
) -> anyhow::Result<()> {
    let mut ui = UI::new();
    if let Err(err) = app.load_entries() {
        ui.show_error(&err);
    }
    let first = app.active_entries().first().map(|e| e.id);
    ui.set_current_entry(first, app);
    if let Some(cmd) = pending {
        let res = match cmd {
            PendingCliCommand::ImportJournals(path) => app.import_entries(&path),
            PendingCliCommand::AssignPriority(p) => app.assign_priority(p),
        };
        match res {
            Ok(()) => {
                let cur = app
                    .current_entry_id
                    .filter(|id| app.get_entry(*id).is_some())
                    .or_else(|| app.active_entries().first().map(|e| e.id));
                ui.set_current_entry(cur, app);
            }
            Err(err) => ui.show_error(&err),
        }
    }
    loop {
        terminal.draw(|f| ui.draw(f, app))?;
        if ui.quit {
            break;
        }
        if !event::poll(Duration::from_millis(500))? {
            continue;
        }
        match event::read()? {
            Event::Key(key) if key.kind == KeyEventKind::Press => {
                ui.handle_key(key, app, terminal)?;
                if ui.quit {
                    break;
                }
            }
            _ => {}
        }
    }
    app.save_state()?;
    Ok(())
}

impl UI {
    fn new() -> Self {
        Self {
            active_control: ControlType::JournalsList,
            popups: Vec::new(),
            list_state: ListState::default(),
            editor: Editor::new(),
            multi_select: false,
            quit: false,
        }
    }

    pub fn show_error(&mut self, err: &anyhow::Error) {
        self.popups.push(Popup::MsgBox(
            MsgBox::error(err.to_string()),
            MsgBoxPurpose::Info,
        ));
    }

    pub fn show_error_text(&mut self, text: &str) {
        self.popups.push(Popup::MsgBox(MsgBox::error(text.to_string()), MsgBoxPurpose::Info));
    }

    pub fn show_info(&mut self, text: String) {
        self.popups.push(Popup::MsgBox(MsgBox::info(text), MsgBoxPurpose::Info));
    }

    pub fn set_current_entry(&mut self, id: Option<u32>, app: &mut App) {
        app.current_entry_id = id;
        let content = id
            .and_then(|id| app.get_entry(id))
            .map(|e| e.content.clone())
            .unwrap_or_default();
        self.editor.set_entry(id, &content);
    }

    fn footer_text(&self, app: &App) -> String {
        let global = global_bindings();
        let fmt = |cmd: Cmd, bindings: &[crate::keymap::Binding]| -> String {
            let keys: Vec<String> = keys_for(bindings, cmd)
                .iter()
                .map(|k| format!("'{}'", k))
                .collect();
            format!("{}: {}", cmd.info().0, keys.join(","))
        };
        let mut parts: Vec<String> = Vec::new();
        if self.multi_select {
            let ms = multi_select_bindings();
            parts.push(fmt(Cmd::LeaveMultiSelectMode, &ms));
            parts.push(fmt(Cmd::ShowHelp, &ms));
            return parts.join(" | ");
        }
        match self.active_control {
            ControlType::JournalsList => {
                parts.push(fmt(Cmd::Quit, &global));
                parts.push(fmt(Cmd::StartEditJournalContent, &global));
                if app.filter.is_some() {
                    parts.push(fmt(Cmd::ResetFilter, &global));
                } else {
                    parts.push(fmt(Cmd::ShowFilter, &global));
                }
                parts.push(fmt(Cmd::ShowSortOptions, &global));
                if app.state.full_screen {
                    parts.push(fmt(Cmd::ToggleFullScreenMode, &global));
                }
                parts.push(fmt(Cmd::ShowHelp, &global));
            }
            ControlType::EntryContentTxt => match self.editor.mode {
                EditorMode::Insert => {
                    parts.push(fmt(Cmd::BackEditorNormalMode, &global));
                    parts.push(" Edit using Emacs motions".to_string());
                }
                _ => {
                    parts.push(fmt(Cmd::Quit, &global));
                    parts.push(fmt(Cmd::StartEditJournalContent, &global));
                    if app.state.full_screen {
                        parts.push(fmt(Cmd::ToggleFullScreenMode, &global));
                    }
                    parts.push(fmt(Cmd::ShowHelp, &global));
                }
            },
        }
        parts.join(" | ")
    }

    pub fn draw(&mut self, f: &mut Frame, app: &App) {
        let area = f.area();
        let footer = self.footer_text(app);
        let footer_h = paragraph_line_count(&footer, area.width) as u16;
        let chunks = Layout::vertical([Constraint::Min(1), Constraint::Length(footer_h)]).split(area);
        let main = chunks[0];
        if app.state.full_screen {
            match self.active_control {
                ControlType::JournalsList => list::render(f, main, app, self),
                ControlType::EntryContentTxt => {
                    self.editor.render(f, main, &app.styles, true);
                }
            }
        } else {
            let parts = Layout::horizontal([Constraint::Percentage(30), Constraint::Percentage(70)])
                .split(main);
            list::render(f, parts[0], app, self);
            let active = self.active_control == ControlType::EntryContentTxt;
            self.editor.render(f, parts[1], &app.styles, active);
        }
        let p = Paragraph::new(footer).wrap(Wrap { trim: false });
        f.render_widget(p, chunks[1]);

        let styles = app.styles.clone();
        for popup in self.popups.iter_mut() {
            match popup {
                Popup::Help(h) => h.render(f),
                Popup::Entry(e) => e.render(f, &styles),
                Popup::MsgBox(m, _) => m.render(f, &styles),
            }
        }
    }

    pub fn handle_key<B: ratatui::backend::Backend>(
        &mut self,
        key: KeyEvent,
        app: &mut App,
        terminal: &mut Terminal<B>,
    ) -> anyhow::Result<()> {
        if let Some(popup) = self.popups.last_mut() {
            match popup {
                Popup::MsgBox(mb, purpose) => {
                    let purpose = *purpose;
                    if let Some(res) = mb.handle_key(&key) {
                        self.popups.pop();
                        self.handle_msgbox_result(purpose, res, app);
                    }
                }
                Popup::Help(h) => {
                    if h.handle_key(&key) {
                        self.popups.pop();
                    }
                }
                Popup::Entry(e) => {
                    let tags = app.all_tags();
                    match e.handle_key(&key, &tags) {
                        EntryPopupResult::None => {}
                        EntryPopupResult::Cancel => {
                            self.popups.pop();
                        }
                        EntryPopupResult::Create(draft) => {
                            self.popups.pop();
                            match app.add_entry(draft) {
                                Ok(id) => {
                                    app.push_undo(Change::AddEntry { id });
                                    self.set_current_entry(Some(id), app);
                                }
                                Err(err) => self.show_error(&err),
                            }
                        }
                        EntryPopupResult::Update(entry) => {
                            self.popups.pop();
                            let old = app.get_entry(entry.id).cloned();
                            match app.update_entry(entry) {
                                Ok(()) => {
                                    if let Some(old) = old {
                                        app.push_undo(Change::EntryAttribute(Box::new(old)));
                                    }
                                }
                                Err(err) => self.show_error(&err),
                            }
                        }
                    }
                }
            }
            return Ok(());
        }
        if self.multi_select {
            return self.handle_multi_select(key, app);
        }
        match self.active_control {
            ControlType::JournalsList => self.handle_list_key(key, app, terminal),
            ControlType::EntryContentTxt => self.handle_editor_key(key, app, terminal),
        }
    }

    fn handle_msgbox_result(&mut self, purpose: MsgBoxPurpose, res: MsgBoxResult, app: &mut App) {
        match purpose {
            MsgBoxPurpose::Info => {}
            MsgBoxPurpose::QuitUnsaved => match res {
                MsgBoxResult::Yes => {
                    if let Err(err) = self.save_content(app) {
                        self.show_error(&err);
                        return;
                    }
                    self.quit = true;
                }
                MsgBoxResult::No => self.quit = true,
                _ => {}
            },
            MsgBoxPurpose::DeleteEntry => {
                if res == MsgBoxResult::Yes {
                    self.delete_current(app);
                }
            }
            MsgBoxPurpose::DeleteSelection => {}
            MsgBoxPurpose::SaveBeforeSwitch => {}
        }
    }

    fn delete_current(&mut self, app: &mut App) {
        let Some(id) = app.current_entry_id else { return };
        let active: Vec<u32> = app.active_entries().iter().map(|e| e.id).collect();
        let pos = active.iter().position(|e| *e == id);
        match app.delete_entry(id) {
            Ok(Some(entry)) => {
                app.push_undo(Change::RemoveEntry(Box::new(entry)));
                let remaining: Vec<u32> = app.active_entries().iter().map(|e| e.id).collect();
                let next = match pos {
                    Some(p) if !remaining.is_empty() => Some(remaining[p.min(remaining.len() - 1)]),
                    _ => remaining.first().copied(),
                };
                self.set_current_entry(next, app);
            }
            Ok(None) => {}
            Err(err) => self.show_error(&err),
        }
    }

    pub fn save_content(&mut self, app: &mut App) -> anyhow::Result<()> {
        let Some(id) = self.editor.entry_id else { return Ok(()) };
        let Some(entry) = app.get_entry(id).cloned() else { return Ok(()) };
        let content = self.editor.content();
        if content == entry.content {
            self.editor.saved_content = content;
            self.editor.refresh_has_unsaved();
            return Ok(());
        }
        let mut new_entry = entry.clone();
        new_entry.content = content.clone();
        app.update_entry(new_entry)?;
        app.push_undo(Change::EntryContent { id, content: entry.content.clone() });
        self.editor.saved_content = content;
        self.editor.refresh_has_unsaved();
        Ok(())
    }

    fn cycle_focus(&mut self) {
        self.active_control = match self.active_control {
            ControlType::JournalsList => ControlType::EntryContentTxt,
            ControlType::EntryContentTxt => ControlType::JournalsList,
        };
        if self.active_control == ControlType::JournalsList && self.editor.mode != EditorMode::Normal {
            self.editor.set_mode(EditorMode::Normal);
        }
    }

    fn try_quit(&mut self) {
        if self.editor.has_unsaved {
            self.popups.push(Popup::MsgBox(
                MsgBox::new(
                    MsgBoxType::Question,
                    MsgBoxActions::YesNoCancel,
                    "Do you want to save the changes on the current journal?".to_string(),
                ),
                MsgBoxPurpose::QuitUnsaved,
            ));
        } else {
            self.quit = true;
        }
    }

    fn select_offset(&mut self, app: &mut App, delta: isize) {
        let active: Vec<u32> = app.active_entries().iter().map(|e| e.id).collect();
        if active.is_empty() {
            return;
        }
        let pos = app
            .current_entry_id
            .and_then(|id| active.iter().position(|e| *e == id));
        let new_pos = match pos {
            Some(p) => (p as isize + delta).clamp(0, active.len() as isize - 1) as usize,
            None => 0,
        };
        if Some(new_pos) != pos {
            self.set_current_entry(Some(active[new_pos]), app);
        }
    }

    fn handle_list_key<B: ratatui::backend::Backend>(
        &mut self,
        key: KeyEvent,
        app: &mut App,
        terminal: &mut Terminal<B>,
    ) -> anyhow::Result<()> {
        let bindings = global_bindings();
        let cmds = lookup(&bindings, &key);
        let Some(cmd) = cmds.into_iter().find(|c| {
            !matches!(
                c,
                Cmd::BackEditorNormalMode
                    | Cmd::ToggleEditorVisualMode
                    | Cmd::CopyOsClipboard
                    | Cmd::CutOsClipboard
                    | Cmd::PasteOsClipboard
            )
        }) else {
            return Ok(());
        };
        self.exec_cmd(cmd, app, terminal)
    }

    fn exec_cmd<B: ratatui::backend::Backend>(
        &mut self,
        cmd: Cmd,
        app: &mut App,
        _terminal: &mut Terminal<B>,
    ) -> anyhow::Result<()> {
        match cmd {
            Cmd::Quit => self.try_quit(),
            Cmd::ShowHelp => {
                let tab = if self.multi_select {
                    2
                } else if self.active_control == ControlType::EntryContentTxt {
                    1
                } else {
                    0
                };
                self.popups.push(Popup::Help(HelpPopup::new(tab)));
            }
            Cmd::CycleFocusedControlForward | Cmd::CycleFocusedControlBack => self.cycle_focus(),
            Cmd::SelectedNextJournal => self.select_offset(app, 1),
            Cmd::SelectedPrevJournal => self.select_offset(app, -1),
            Cmd::GoToTopJournal => self.select_offset(app, isize::MIN / 2),
            Cmd::GoToBottomJournal => self.select_offset(app, isize::MAX / 2),
            Cmd::PageUpJournals => {
                let n = app.settings.scroll_per_page as isize;
                self.select_offset(app, -n)
            }
            Cmd::PageDownJournals => {
                let n = app.settings.scroll_per_page as isize;
                self.select_offset(app, n)
            }
            Cmd::CreateJournal => self.popups.push(Popup::Entry(EntryPopup::new_entry())),
            Cmd::EditCurrentJournal => {
                if let Some(entry) = app.current_entry() {
                    self.popups.push(Popup::Entry(EntryPopup::edit_entry(entry)));
                }
            }
            Cmd::DeleteCurrentJournal => {
                if app.current_entry_id.is_some() {
                    self.popups.push(Popup::MsgBox(
                        MsgBox::new(
                            MsgBoxType::Question,
                            MsgBoxActions::YesNo,
                            "Do you want to remove the current journal?".to_string(),
                        ),
                        MsgBoxPurpose::DeleteEntry,
                    ));
                }
            }
            Cmd::StartEditJournalContent => {
                if app.current_entry_id.is_some() {
                    self.active_control = ControlType::EntryContentTxt;
                    self.editor.set_mode(EditorMode::Insert);
                }
            }
            Cmd::BackEditorNormalMode => {
                if self.active_control == ControlType::EntryContentTxt {
                    self.editor.set_mode(EditorMode::Normal);
                }
            }
            Cmd::SaveJournalContent => {
                if let Err(err) = self.save_content(app) {
                    self.show_error(&err);
                }
            }
            Cmd::DiscardChangesJournalContent => {
                let id = self.editor.entry_id;
                self.set_current_entry(id, app);
            }
            Cmd::ReloadAll => {
                if let Err(err) = app.load_entries() {
                    self.show_error(&err);
                }
                let cur = app
                    .current_entry_id
                    .filter(|id| app.get_entry(*id).is_some())
                    .or_else(|| app.active_entries().first().map(|e| e.id));
                self.set_current_entry(cur, app);
            }
            Cmd::ToggleFullScreenMode => {
                app.state.full_screen = !app.state.full_screen;
            }
            Cmd::ToggleEditorVisualMode => {
                if self.editor.mode == EditorMode::Visual {
                    self.editor.set_mode(EditorMode::Normal);
                } else {
                    self.editor.set_mode(EditorMode::Visual);
                }
            }
            Cmd::CopyOsClipboard | Cmd::CutOsClipboard | Cmd::PasteOsClipboard => {
                self.show_error_text(CLIPBOARD_ERROR);
            }
            Cmd::EnterMultiSelectMode => {
                self.multi_select = true;
            }
            _ => {}
        }
        Ok(())
    }

    fn handle_editor_key<B: ratatui::backend::Backend>(
        &mut self,
        key: KeyEvent,
        app: &mut App,
        terminal: &mut Terminal<B>,
    ) -> anyhow::Result<()> {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        if self.editor.mode == EditorMode::Insert {
            match key.code {
                KeyCode::Esc => {
                    self.editor.set_mode(EditorMode::Normal);
                    return Ok(());
                }
                KeyCode::Char('c') | KeyCode::Char('[') if ctrl => {
                    self.editor.set_mode(EditorMode::Normal);
                    return Ok(());
                }
                KeyCode::Char('v') | KeyCode::Char('x') | KeyCode::Char('p') if ctrl => {
                    self.show_error_text(CLIPBOARD_ERROR);
                    return Ok(());
                }
                _ => {}
            }
            self.editor.textarea.input(key);
            self.editor.refresh_has_unsaved();
            return Ok(());
        }
        // normal & visual
        match self.editor.handle_vim(&key) {
            VimResult::Handled => {
                self.editor.refresh_has_unsaved();
                return Ok(());
            }
            VimResult::ClipboardError => {
                self.show_error_text(CLIPBOARD_ERROR);
                return Ok(());
            }
            VimResult::NotHandled => {}
        }
        let bindings = global_bindings();
        let cmds = lookup(&bindings, &key);
        let editor_cmd = cmds.into_iter().find(|c| {
            matches!(
                c,
                Cmd::Quit
                    | Cmd::ShowHelp
                    | Cmd::CycleFocusedControlForward
                    | Cmd::CycleFocusedControlBack
                    | Cmd::StartEditJournalContent
                    | Cmd::BackEditorNormalMode
                    | Cmd::SaveJournalContent
                    | Cmd::DiscardChangesJournalContent
                    | Cmd::ReloadAll
                    | Cmd::EditInExternalEditor
                    | Cmd::ToggleFullScreenMode
                    | Cmd::CopyOsClipboard
                    | Cmd::CutOsClipboard
                    | Cmd::PasteOsClipboard
            )
        });
        if let Some(cmd) = editor_cmd {
            if cmd == Cmd::EditInExternalEditor && key.code == KeyCode::Char('y') && !ctrl {
                return Ok(());
            }
            return self.exec_cmd(cmd, app, terminal);
        }
        if self.editor.handle_navigation(&key) {
            self.editor.refresh_has_unsaved();
        }
        Ok(())
    }

    fn handle_multi_select(&mut self, key: KeyEvent, app: &mut App) -> anyhow::Result<()> {
        let bindings = multi_select_bindings();
        let cmds = lookup(&bindings, &key);
        let Some(cmd) = cmds.into_iter().next() else { return Ok(()) };
        match cmd {
            Cmd::ShowHelp => self.popups.push(Popup::Help(HelpPopup::new(2))),
            Cmd::SelectedNextJournal => self.select_offset(app, 1),
            Cmd::SelectedPrevJournal => self.select_offset(app, -1),
            Cmd::LeaveMultiSelectMode => {
                self.multi_select = false;
                app.selected_entries.clear();
            }
            Cmd::MulSelToggleSelected => {
                if let Some(id) = app.current_entry_id {
                    if !app.selected_entries.remove(&id) {
                        app.selected_entries.insert(id);
                    }
                }
            }
            Cmd::MulSelSelectAll => {
                let ids: Vec<u32> = app.active_entries().iter().map(|e| e.id).collect();
                app.selected_entries.extend(ids);
            }
            Cmd::MulSelSelectNone => app.selected_entries.clear(),
            Cmd::MulSelInverse => {
                let ids: Vec<u32> = app.active_entries().iter().map(|e| e.id).collect();
                for id in ids {
                    if !app.selected_entries.remove(&id) {
                        app.selected_entries.insert(id);
                    }
                }
            }
            _ => {}
        }
        Ok(())
    }
}

