};
use ratatui::Frame;

use super::{ControlType, UI};
use crate::app::App;
use crate::entry::Entry;
use crate::settings::DatumVisibility;
use crate::textwrap::{display_width, wrap};

const LIST_INNER_MARGIN: usize = 5;

pub fn tag_color(index: usize) -> Option<Style> {
    let c = |fg: Color, bg: Color| Some(Style::default().fg(fg).bg(bg));
    match index {
        0 => c(Color::Black, Color::LightCyan),
        1 => c(Color::Black, Color::LightRed),
        2 => c(Color::Black, Color::LightGreen),
        3 => c(Color::Reset, Color::DarkGray),
        4 => c(Color::Black, Color::LightYellow),
        5 => c(Color::Reset, Color::Red),
        6 => c(Color::Yellow, Color::Blue),
        7 => c(Color::Red, Color::Cyan),
        8 => c(Color::Black, Color::LightMagenta),
        _ => None,
    }
}

pub fn build_item_lines(
    entry: &Entry,
    app: &App,
    width: usize,
    active: bool,
    selected_in_multi: bool,
    all_tags: &[String],
) -> Vec<Line<'static>> {
    let styles = &app.styles.journals_list;
    let mut lines: Vec<Line<'static>> = Vec::new();
    let max_width = width.saturating_sub(LIST_INNER_MARGIN);
    let (title, title_style): (String, Style) = if selected_in_multi {
        (format!("* {}", entry.title), styles.title_selected.into())
    } else if active {
        (entry.title.clone(), styles.title_active.into())
    } else {
        (entry.title.clone(), styles.title_inactive.into())
    };
    for l in wrap(&title, max_width) {
        lines.push(Line::from(Span::styled(l, title_style)));
    }
    let date_style: Style = styles.date_priority.into();
    let date = format!(
        "{},{},{}",
        entry.date.day(),
        entry.date.month(),
        entry.date.year()
    );
    match app.settings.datum_visibility {
        DatumVisibility::Show => match entry.priority {
            Some(p) => {
                let pr = format!("Priority: {p}");
                let combined = format!("{date} | {pr}");
                if display_width(&combined) <= max_width {
                    lines.push(Line::from(Span::styled(combined, date_style)));
                } else {
                    lines.push(Line::from(Span::styled(date, date_style)));
                    lines.push(Line::from(Span::styled(pr, date_style)));
                }
            }
            None => lines.push(Line::from(Span::styled(date, date_style))),
        },
        DatumVisibility::EmptyLine => match entry.priority {
            Some(p) => lines.push(Line::from(Span::styled(format!("Priority: {p}"), date_style))),
            None => lines.push(Line::default()),
        },
        DatumVisibility::Hide => {
            if let Some(p) = entry.priority {
                lines.push(Line::from(Span::styled(format!("Priority: {p}"), date_style)));
            }
        }
    }
    if !entry.tags.is_empty() {
        let default_style: Style = styles.tags_default.into();
        let mut spans: Vec<Span<'static>> = Vec::new();
        for (i, tag) in entry.tags.iter().enumerate() {
            if i > 0 {
                spans.push(Span::styled(" | ", default_style));
            }
            let style = if app.settings.colored_tags {
                all_tags
                    .iter()
                    .position(|t| t == tag)
                    .and_then(tag_color)
                    .unwrap_or_default()
            } else {
                default_style
            };
            spans.push(Span::styled(tag.clone(), style));
        }
        let tags_width = width.saturating_sub(LIST_INNER_MARGIN + 1);
        let mut cur: Vec<Span<'static>> = Vec::new();
        let mut cur_w = 0usize;
        for s in spans {
            let w = display_width(&s.content);
            if cur_w + w > tags_width {
                lines.push(Line::from(std::mem::take(&mut cur)));
                cur_w = 0;
            }
            cur_w += w;
            cur.push(s);
        }
        lines.push(Line::from(cur));
    }
    lines
}

pub fn render(f: &mut Frame, area: Rect, app: &App, ui: &mut UI) {
    let active = ui.active_control == ControlType::JournalsList;
    let styles = &app.styles.journals_list;
    let mut title = "Journals".to_string();
    if ui.multi_select {
        title.push_str(" - Multi-Select");
    } else if app.filter.is_some() {
        title.push_str(" - Filtered");
    }
    let border_style: Style = if ui.multi_select {
        styles.block_multi_select.into()
    } else if active {
        styles.block_active.into()
    } else {
        styles.block_inactive.into()
    };
    let entries = app.active_entries();
    let mut block = Block::default()
        .borders(Borders::ALL)
        .title(title)
        .border_style(border_style);

    if entries.is_empty() {
        let p = Paragraph::new(Text::from(vec![
            Line::default(),
            Line::from("Use 'n' to create new entry"),
        ]))
        .alignment(Alignment::Center)
        .wrap(Wrap { trim: false })
