    viewport_content_length: usize,
) {
    let (begin, end, track, thumb) = match orientation {
        SbOrientation::VerticalRight => ("▲", "▼", "│", "█"),
        SbOrientation::HorizontalBottom => ("◄", "►", "─", "🬋"),
    };
    let len = match orientation {
        SbOrientation::VerticalRight => area.height,
        SbOrientation::HorizontalBottom => area.width,
    };
    let track_length_u = len.saturating_sub(2);
    if content_length == 0 || track_length_u == 0 {
        return;
    }
    let track_length = track_length_u as f64;
    let viewport_length = if viewport_content_length != 0 {
        viewport_content_length as f64
    } else {
        len as f64
    };
    let max_position = content_length.saturating_sub(1) as f64;
    let start_position = (position as f64).clamp(0.0, max_position);
    let max_viewport_position = max_position + viewport_length;
    let end_position = start_position + viewport_length;
    let thumb_start = start_position * track_length / max_viewport_position;
    let thumb_end = end_position * track_length / max_viewport_position;
    let thumb_start = thumb_start.round().clamp(0.0, track_length - 1.0) as usize;
    let thumb_end = thumb_end.round().clamp(0.0, track_length) as usize;
    let thumb_length = thumb_end.saturating_sub(thumb_start).max(1);
    let track_end_length = (track_length as usize).saturating_sub(thumb_start + thumb_length);

    let mut symbols: Vec<&str> = Vec::new();
    symbols.push(begin);
    symbols.extend(std::iter::repeat(track).take(thumb_start));
    symbols.extend(std::iter::repeat(thumb).take(thumb_length));
    symbols.extend(std::iter::repeat(track).take(track_end_length));
    symbols.push(end);
    let style = Style::default();
    match orientation {
        SbOrientation::VerticalRight => {
            if area.width == 0 {
                return;
            }
            let x = area.right() - 1;
            for (i, s) in symbols.iter().enumerate() {
                let y = area.top() + i as u16;
                if y >= area.bottom() {
                    break;
                }
                buf.set_string(x, y, s, style);
            }
        }
        SbOrientation::HorizontalBottom => {
            if area.height == 0 {
                return;
            }
            let y = area.bottom() - 1;
            for (i, s) in symbols.iter().enumerate() {
                let x = area.left() + i as u16;
                if x >= area.right() {
                    break;
                }
                buf.set_string(x, y, s, style);
            }
        }
    }
}
