use std::path::PathBuf;

use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use ratatui::layout::{Alignment, Constraint, Layout, Margin};
use ratatui::style::Style;
use ratatui::widgets::{Block, Borders, Clear, Paragraph, Wrap};
use ratatui::Frame;

use super::layout::centered_rect_exact_height;
use crate::textarea::{CursorMove, TextArea};
use crate::theme::Styles;

const FOOTER_TEXT: &str = "Enter: confirm | Esc or <Ctrl-c>: Cancel";

pub enum ExportKind {
    Single { id: u32, title: String },
    Multi { ids: Vec<u32> },
}

pub enum ExportResult {
    None,
    Cancel,
    Export(PathBuf),
}

pub struct ExportPopup {
    pub kind: ExportKind,
    path_txt: TextArea,
    error: Option<String>,
}

impl ExportPopup {
    pub fn new(kind: ExportKind, default_dir: Option<PathBuf>) -> Self {
        let file_name = match &kind {
            ExportKind::Single { title, .. } => format!("{title}.txt"),
            ExportKind::Multi { .. } => "tjournal_export.json".to_string(),
        };
        let dir = match default_dir {
            Some(d) => d,
            None => std::env::current_dir().unwrap_or_default(),
        };
        let path = dir.join(file_name);
        let mut ta = TextArea::new(vec![path.to_string_lossy().into_owned()]);
        ta.move_cursor(CursorMove::End);
        Self {
            kind,
            path_txt: ta,
            error: None,
        }
    }

    fn path_text(&self) -> String {
        self.path_txt.lines().first().cloned().unwrap_or_default()
    }

    fn validate(&mut self) {
        self.error = if self.path_text().is_empty() {
            Some("Path can't be empty".to_string())
        } else {
            None
        };
    }

    pub fn render(&mut self, f: &mut Frame, styles: &Styles) {
        let area = centered_rect_exact_height(70, 11, f.area());
        let title = match self.kind {
            ExportKind::Single { .. } => "Export journal content",
            ExportKind::Multi { .. } => "Export journals",
        };
        let block = Block::default().borders(Borders::ALL).title(title);
        f.render_widget(Clear, area);
        let inner = block.inner(area).inner(Margin::new(3, 1));
        f.render_widget(block, area);
        let chunks = Layout::vertical([
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(3),
            Constraint::Length(1),
            Constraint::Min(1),
        ])
        .split(inner);
        let text = match &self.kind {
            ExportKind::Single { title, .. } => format!("Journal: {title}"),
            ExportKind::Multi { ids } => format!("Export the selected {} journals", ids.len()),
        };
        f.render_widget(Paragraph::new(text), chunks[0]);

        let (style, cursor_style, title): (Style, Style, String) = match &self.error {
            Some(err) => (
                styles.general.input_block_invalid.into(),
                styles.general.input_corsur_invalid.into(),
                format!("Path : {err}"),
            ),
            None => (
                styles.general.input_block_active.into(),
                styles.general.input_corsur_active.into(),
                "Path".to_string(),
            ),
        };
        self.path_txt.set_cursor_line_style(Style::default());
        self.path_txt.set_cursor_style(cursor_style);
        self.path_txt.set_style(style);
        self.path_txt
            .set_block(Block::default().borders(Borders::ALL).title(title).style(style));
        self.path_txt.render(chunks[2], f.buffer_mut());

        let footer = Paragraph::new(FOOTER_TEXT)
            .alignment(Alignment::Center)
            .wrap(Wrap { trim: false });
        f.render_widget(footer, chunks[4]);
    }

    pub fn handle_key(&mut self, key: &KeyEvent) -> ExportResult {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Enter => {
                self.validate();
                if self.error.is_some() {
                    return ExportResult::None;
                }
                return ExportResult::Export(PathBuf::from(self.path_text()));
            }
            KeyCode::Esc => return ExportResult::Cancel,
            KeyCode::Char('c') if ctrl => return ExportResult::Cancel,
            _ => {}
        }
        if self.path_txt.input(*key) {
            self.validate();
        }
        ExportResult::None
    }
}
