cat > /workspace/src/ui/filter_popup.rs <<'EOF'
use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use ratatui::layout::{Alignment, Constraint, Layout, Margin};
use ratatui::style::Style;
use ratatui::widgets::{Block, BorderType, Borders, Clear, List, ListItem, ListState, Paragraph, Wrap};
use ratatui::Frame;

use super::layout::centered_rect;
use super::util::paragraph_line_count;
use crate::app::{CriteriaRelation, Filter, FilterCriterion};
use crate::textarea::{CursorMove, TextArea};
use crate::theme::Styles;

const FOOTER_TEXT: &str = "Tab: Change focused control | Enter or <Ctrl-m>: Confirm | Esc or <Ctrl-c>: Cancel | <Ctrl-r>: Change Matching Logic | <Space>: Tags Toggle Selected";

pub enum FilterResult {
    None,
    Cancel,
    Apply(Option<Filter>),
}

pub struct FilterPopup {
    relation: CriteriaRelation,
    fields: [TextArea; 3],
    priority_err: Option<String>,
    tags: Vec<String>,
    selected_tags: Vec<String>,
    tags_state: ListState,
    active: usize,
}

fn text_area_with(text: &str) -> TextArea {
    let mut ta = TextArea::new(vec![text.to_string()]);
    ta.move_cursor(CursorMove::End);
    ta
}

impl FilterPopup {
    pub fn new(all_tags: Vec<String>, filter: Option<&Filter>) -> Self {
        let mut title = String::new();
        let mut content = String::new();
        let mut priority = String::new();
        let mut selected_tags = Vec::new();
        let mut relation = CriteriaRelation::And;
        if let Some(f) = filter {
            relation = f.relation;
            for c in &f.criteria {
                match c {
                    FilterCriterion::Title(t) => title = t.clone(),
                    FilterCriterion::Content(t) => content = t.clone(),
                    FilterCriterion::Priority(p) => priority = p.to_string(),
                    FilterCriterion::Tag(t) => selected_tags.push(t.clone()),
                    FilterCriterion::NoTags => {}
                }
            }
        }
        let mut tags_state = ListState::default();
        if !all_tags.is_empty() {
            tags_state.select(Some(0));
        }
        Self {
            relation,
            fields: [
                text_area_with(&title),
                text_area_with(&content),
                text_area_with(&priority),
            ],
            priority_err: None,
            tags: all_tags,
            selected_tags,
            tags_state,
            active: 0,
        }
    }

    fn field_text(&self, i: usize) -> String {
        self.fields[i].lines().first().cloned().unwrap_or_default()
    }

    fn validate_priority(&mut self) {
        let text = self.field_text(2);
        self.priority_err = if text.is_empty() || text.parse::<u32>().is_ok() {
            None
        } else {
            Some("Priority must be a positive number".to_string())
        };
    }

    pub fn render(&mut self, f: &mut Frame, styles: &Styles) {
        let area = centered_rect(70, 80, f.area());
        let block = Block::default().borders(Borders::ALL).title("Filter");
        f.render_widget(Clear, area);
        let inner = block.inner(area).inner(Margin::new(3, 1));
        f.render_widget(block, area);
        let footer_lines = paragraph_line_count(FOOTER_TEXT, inner.width) as u16;
        let chunks = Layout::vertical([
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Min(1),
            Constraint::Length(footer_lines),
        ])
        .split(inner);

        let logic_text = match self.relation {
            CriteriaRelation::And => "Journals must meet all criteria",
            CriteriaRelation::Or => "Journals must meet any of the criteria",
        };
        let logic = Paragraph::new(logic_text).alignment(Alignment::Center).block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .title("Matching Logic"),
        );
        f.render_widget(logic, chunks[0]);

        let names = ["Title", "Content", "Priority"];
        for i in 0..3 {
            let focused = self.active == i;
            let err = if i == 2 { self.priority_err.clone() } else { None };
            let title = match &err {
                Some(e) => format!("{} : {}", names[i], e),
                None => names[i].to_string(),
            };
            let style: Style = if err.is_some() {
                styles.general.input_block_invalid.into()
            } else if focused {
                styles.general.input_block_active.into()
            } else {
                Style::default()
            };
            let cursor: Style = if focused {
                if err.is_some() {
                    styles.general.input_corsur_invalid.into()
                } else {
                    styles.general.input_corsur_active.into()
                }
            } else {
                Style::default()
            };
            let ta = &mut self.fields[i];
            ta.set_cursor_line_style(Style::default());
            ta.set_cursor_style(cursor);
            ta.set_style(style);
            ta.set_block(Block::default().borders(Borders::ALL).title(title).style(style));
            ta.render(chunks[i + 1], f.buffer_mut());
        }

        let tags_focused = self.active == 3;
        let mut tags_block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title("Tags");
        if tags_focused {
            tags_block = tags_block.border_style(Style::from(styles.general.input_block_active));
        }
        let selected_style: Style = styles.general.list_item_selected.into();
        let items: Vec<ListItem> = self
            .tags
            .iter()
            .map(|t| {
                if self.selected_tags.contains(t) {
                    ListItem::new(format!("* {t}")).style(selected_style)
                } else {
                    ListItem::new(t.as_str())
                }
            })
            .collect();
        let highlight: Style = if tags_focused {
            styles.general.list_highlight_active.into()
        } else {
            styles.general.list_highlight_inactive.into()
        };
        let list = List::new(items)
            .block(tags_block)
            .highlight_symbol(">> ")
            .highlight_style(highlight);
        f.render_stateful_widget(list, chunks[4], &mut self.tags_state);

        let footer = Paragraph::new(FOOTER_TEXT)
            .alignment(Alignment::Center)
            .wrap(Wrap { trim: false });
        f.render_widget(footer, chunks[5]);
    }

    pub fn handle_key(&mut self, key: &KeyEvent) -> FilterResult {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Tab => {
                self.active = (self.active + 1) % 4;
                return FilterResult::None;
            }
            KeyCode::Enter => return self.confirm(),
            KeyCode::Char('m') if ctrl => return self.confirm(),
            KeyCode::Esc => return FilterResult::Cancel,
            KeyCode::Char('c') if ctrl => return FilterResult::Cancel,
            KeyCode::Char('r') if ctrl => {
                self.relation = match self.relation {
                    CriteriaRelation::And => CriteriaRelation::Or,
                    CriteriaRelation::Or => CriteriaRelation::And,
                };
                return FilterResult::None;
            }
            _ => {}
        }
        if self.active == 3 {
            let len = self.tags.len();
            match key.code {
                KeyCode::Char('j') | KeyCode::Down => {
                    if len > 0 {
                        let i = match self.tags_state.selected() {
                            Some(i) if i + 1 < len => i + 1,
                            Some(_) => 0,
                            None => 0,
                        };
                        self.tags_state.select(Some(i));
                    }
                }
                KeyCode::Char('k') | KeyCode::Up => {
                    if len > 0 {
                        let i = match self.tags_state.selected() {
                            Some(0) | None => len - 1,
                            Some(i) => i - 1,
                        };
                        self.tags_state.select(Some(i));
                    }
                }
                KeyCode::Char(' ') => {
                    if let Some(i) = self.tags_state.selected() {
                        let tag = self.tags[i].clone();
                        if let Some(pos) = self.selected_tags.iter().position(|t| *t == tag) {
                            self.selected_tags.remove(pos);
                        } else {
                            self.selected_tags.push(tag);
                        }
                    }
                }
                _ => {}
            }
            return FilterResult::None;
        }
        let i = self.active;
        if self.fields[i].input(*key) && i == 2 {
            self.validate_priority();
        }
        FilterResult::None
    }

    fn confirm(&mut self) -> FilterResult {
        self.validate_priority();
        if self.priority_err.is_some() {
            return FilterResult::None;
        }
        let mut criteria = Vec::new();
        let title = self.field_text(0);
        if !title.is_empty() {
            criteria.push(FilterCriterion::Title(title));
        }
        let content = self.field_text(1);
        if !content.is_empty() {
            criteria.push(FilterCriterion::Content(content));
        }
        let priority = self.field_text(2);
        if let Ok(p) = priority.parse::<u32>() {
            criteria.push(FilterCriterion::Priority(p));
        }
        for t in &self.tags {
            if self.selected_tags.contains(t) {
                criteria.push(FilterCriterion::Tag(t.clone()));
            }
        }
        if criteria.is_empty() {
            FilterResult::Apply(None)
        } else {
            FilterResult::Apply(Some(Filter {
                relation: self.relation,
                criteria,
            }))
        }
    }
}
