use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use ratatui::layout::{Alignment, Constraint, Layout, Margin};
use ratatui::style::Style;
use ratatui::widgets::{Block, BorderType, Borders, Clear, List, ListItem, ListState, Paragraph, Wrap};
use ratatui::Frame;

use super::layout::centered_rect;
use super::util::paragraph_line_count;
use crate::app::{SortCriteria, SortOrder, Sorter};
use crate::theme::Styles;

const FOOTER_TEXT: &str = "Tab: Change focused control | Enter or <Ctrl-m>: Confirm | Esc or <Ctrl-c>: Cancel |<o>: Change Sort Order | <Space>: Move criteria to other list |<j/k> or <up/down> cycle between criteria | <Ctrl-d> Load default";

pub enum SortResult {
    None,
    Cancel,
    Apply(Sorter),
}

pub struct SortPopup {
    order: SortOrder,
    available: Vec<SortCriteria>,
    applied: Vec<SortCriteria>,
    available_state: ListState,
    applied_state: ListState,
    focus_applied: bool,
}

fn state_for(len: usize) -> ListState {
    let mut s = ListState::default();
    if len > 0 {
        s.select(Some(0));
    }
    s
}

impl SortPopup {
    pub fn new(sorter: &Sorter) -> Self {
        let applied = sorter.criteria.clone();
        let available: Vec<SortCriteria> = SortCriteria::all()
            .into_iter()
            .filter(|c| !applied.contains(c))
            .collect();
        Self {
            order: sorter.order,
            available_state: state_for(available.len()),
            applied_state: state_for(applied.len()),
            available,
            applied,
            focus_applied: false,
        }
    }

    fn load_default(&mut self) {
        let def = Sorter::default();
        self.order = def.order;
        self.applied = def.criteria.clone();
        self.available = SortCriteria::all()
            .into_iter()
            .filter(|c| !self.applied.contains(c))
            .collect();
        self.available_state = state_for(self.available.len());
        self.applied_state = state_for(self.applied.len());
    }

    pub fn render(&mut self, f: &mut Frame, styles: &Styles) {
        let area = centered_rect(70, 80, f.area());
        let block = Block::default().borders(Borders::ALL).title("Sort");
        f.render_widget(Clear, area);
        let inner = block.inner(area).inner(Margin::new(3, 1));
        f.render_widget(block, area);
        let footer_lines = paragraph_line_count(FOOTER_TEXT, inner.width) as u16;
        let chunks = Layout::vertical([
            Constraint::Length(3),
            Constraint::Percentage(50),
            Constraint::Percentage(50),
            Constraint::Length(footer_lines),
        ])
        .split(inner);
        let order_text = match self.order {
            SortOrder::Ascending => "Ascending",
            SortOrder::Descending => "Descending",
        };
        let order = Paragraph::new(order_text)
            .alignment(Alignment::Center)
            .block(Block::default().borders(Borders::ALL).title("Sort Order"));
        f.render_widget(order, chunks[0]);

        let active_style: Style = styles.general.input_block_active.into();
        let invalid_style: Style = styles.general.input_block_invalid.into();
        for (i, applied) in [false, true].iter().enumerate() {
            let focused = self.focus_applied == *applied;
            let (items, state, title) = if *applied {
                (&self.applied, &mut self.applied_state, "Applied Criteria")
            } else {
                (&self.available, &mut self.available_state, "Available Criteria")
            };
            let mut block = Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded)
                .title(title);
            if *applied && items.is_empty() {
                block = block.title("").title("Applied criteria can't be empty");
                block = Block::default()
                    .borders(Borders::ALL)
                    .border_type(BorderType::Rounded)
                    .title("Applied criteria can't be empty")
                    .border_style(invalid_style);
            } else if focused {
                block = block.border_style(active_style);
            }
            let list_items: Vec<ListItem> = items.iter().map(|c| ListItem::new(c.name())).collect();
            let highlight: Style = if focused {
                styles.general.list_highlight_active.into()
            } else {
                styles.general.list_highlight_inactive.into()
            };
            let list = List::new(list_items)
                .block(block)
                .highlight_symbol(">> ")
                .highlight_style(highlight);
            f.render_stateful_widget(list, chunks[1 + i], state);
        }

        let footer = Paragraph::new(FOOTER_TEXT)
            .alignment(Alignment::Center)
            .wrap(Wrap { trim: false });
        f.render_widget(footer, chunks[3]);
    }

    pub fn handle_key(&mut self, key: &KeyEvent) -> SortResult {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Tab => self.focus_applied = !self.focus_applied,
            KeyCode::Enter => return self.confirm(),
            KeyCode::Char('m') if ctrl => return self.confirm(),
            KeyCode::Esc => return SortResult::Cancel,
            KeyCode::Char('c') if ctrl => return SortResult::Cancel,
            KeyCode::Char('d') if ctrl => self.load_default(),
            KeyCode::Char('o') => {
                self.order = match self.order {
                    SortOrder::Ascending => SortOrder::Descending,
                    SortOrder::Descending => SortOrder::Ascending,
                }
            }
            KeyCode::Char('j') | KeyCode::Down => {
                let (len, state) = self.focused();
                if len > 0 {
                    let i = match state.selected() {
                        Some(i) if i + 1 < len => i + 1,
                        _ => 0,
                    };
                    state.select(Some(i));
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                let (len, state) = self.focused();
                if len > 0 {
                    let i = match state.selected() {
                        Some(0) | None => len - 1,
                        Some(i) => i - 1,
                    };
                    state.select(Some(i));
                }
            }
            KeyCode::Char(' ') => self.move_selected(),
            _ => {}
        }
        SortResult::None
    }

    fn focused(&mut self) -> (usize, &mut ListState) {
        if self.focus_applied {
            (self.applied.len(), &mut self.applied_state)
        } else {
            (self.available.len(), &mut self.available_state)
        }
    }

    fn move_selected(&mut self) {
        let (src, src_state, dst, dst_state) = if self.focus_applied {
            (
                &mut self.applied,
                &mut self.applied_state,
                &mut self.available,
                &mut self.available_state,
            )
        } else {
            (
                &mut self.available,
                &mut self.available_state,
                &mut self.applied,
                &mut self.applied_state,
            )
        };
        let Some(i) = src_state.selected() else { return };
        if i >= src.len() {
            return;
        }
        let item = src.remove(i);
        dst.push(item);
        if src.is_empty() {
            src_state.select(None);
        } else if i >= src.len() {
            src_state.select(Some(src.len() - 1));
        }
        if dst_state.selected().is_none() {
            dst_state.select(Some(0));
        }
    }

    fn confirm(&mut self) -> SortResult {
        if self.applied.is_empty() {
            return SortResult::None;
        }
        SortResult::Apply(Sorter {
            criteria: self.applied.clone(),
            order: self.order,
        })
    }
}
