    EntryContent { id: u32, content: String },
}

impl Change {
    fn remap_id(&mut self, old: u32, new: u32) {
        match self {
            Change::AddEntry { id } | Change::EntryContent { id, .. } => {
                if *id == old {
                    *id = new;
                }
            }
            Change::RemoveEntry(e) | Change::EntryAttribute(e) => {
