            stack.drain(0..excess);
        }
    }

    fn remap_history(&mut self, old: u32, new: u32) {
        for c in self.undo_stack.iter_mut().chain(self.redo_stack.iter_mut()) {
            c.remap_id(old, new);
        }
    }

    /// Reverts the change and returns the change that reverts the applied operation
    /// together with the id of the affected entry
    fn apply_inverse(&mut self, change: Change) -> anyhow::Result<(Change, Option<u32>)> {
        match change {
            Change::AddEntry { id } => {
                let removed = self.delete_entry(id)?;
