{"command":"cat > /workspace/src/fuzzy.rs <<'EOF'
//! Fuzzy matching (skim-v2 like scoring)

#[derive(Clone, Copy, PartialEq, Eq)]
enum CharType {
    Empty,
    HardSep,
    SoftSep,
    Number,
    Upper,
    Lower,
}

fn char_type(ch: char) -> CharType {
    match ch {
        '\0' => CharType::Empty,
        ' ' | '/' | '\\' | '|' | '(' | ')' | '[' | ']' | '{' | '}' => CharType::HardSep,
        '!'..='\'' | '*'..='.' | ':'..='@' | '^'..='`' | '~' => CharType::SoftSep,
        '0'..='9' => CharType::Number,
        'A'..='Z' => CharType::Upper,
        _ => CharType::Lower,
    }
}

const SCORE_MATCH: i32 = 16;
const GAP_START: i32 = -4;
const GAP_EXTENSION: i32 = -1;
const BONUS_FIRST_CHAR_MULTIPLIER: i32 = 2;
const BONUS_HEAD: i32 = 8;
const BONUS_BREAK: i32 = 7;
const BONUS_CAMEL: i32 = 6;
const BONUS_CONSECUTIVE: i32 = 4;
const PENALTY_CASE_MISMATCH: i32 = -2;
const NEG_INF: i32 = i32::MIN / 4;

fn in_place_bonus(prev: char, cur: char) -> i32 {
    use CharType::*;
    match (char_type(prev), char_type(cur)) {
        (Empty, _) | (HardSep, _) => BONUS_HEAD,
        (SoftSep, _) => BONUS_BREAK,
        (Lower, Upper) | (Number, Upper) => BONUS_CAMEL,
        _ => 0,
    }
}

fn chars_equal(a: char, b: char, case_sensitive: bool) -> bool {
    if case_sensitive {
        a == b
    } else {
        a == b || a.to_lowercase().eq(b.to_lowercase())
    }
}

/// Returns score and matched char indices (in chars)
pub fn fuzzy_indices(choice: &str, pattern: &str) -> Option<(i32, Vec<usize>)> {
    if pattern.is_empty() {
        return Some((0, Vec::new()));
    }
    let case_sensitive = pattern.chars().any(|c| c.is_uppercase());
    let c: Vec<char> = choice.chars().collect();
    let p: Vec<char> = pattern.chars().collect();
    let n = p.len();
    let m = c.len();
    // quick subsequence check
    {
        let mut pi = 0;
        for &ch in &c {
            if pi < n && chars_equal(ch, p[pi], case_sensitive) {
                pi += 1;
            }
        }
        if pi < n {
            return None;
        }
    }
    let mut bonus = vec![0i32; m];
    let mut prev = '\0';
    for (j, &ch) in c.iter().enumerate() {
        bonus[j] = in_place_bonus(prev, ch);
        prev = ch;
    }
    if m > 0 {
        bonus[0] *= BONUS_FIRST_CHAR_MULTIPLIER;
    }
    // matrices with (n+1) rows and (m+1) cols
    let cols = m + 1;
    let mut ms = vec![NEG_INF; (n + 1) * cols];
    let mut ps = vec![NEG_INF; (n + 1) * cols];
    // moves: true if came from match (consecutive / gap start)
    let mut m_from_diag_m = vec![false; (n + 1) * cols];
    let mut p_from_m = vec![false; (n + 1) * cols];
    for j in 0..cols {
        ps[j] = 0;
    }
    for i in 1..=n {
        for j in 1..=m {
            let idx = i * cols + j;
            let diag = (i - 1) * cols + (j - 1);
            let left = i * cols + (j - 1);
            if chars_equal(c[j - 1], p[i - 1], case_sensitive) {
                let mut score = SCORE_MATCH;
                if !case_sensitive && c[j - 1] != p[i - 1] {
                    score += PENALTY_CASE_MISMATCH;
                }
                let b = bonus[j - 1];
                let consecutive = b.max(BONUS_CONSECUTIVE);
                let score_match = if ms[diag] > NEG_INF { ms[diag] + consecutive } else { NEG_INF };
                let score_skip = if ps[diag] > NEG_INF { ps[diag] + b } else { NEG_INF };
                if score_match >= score_skip {
                    ms[idx] = if score_match > NEG_INF { score_match + score } else { NEG_INF };
                    m_from_diag_m[idx] = true;
                } else {
                    ms[idx] = score_skip + score;
                    m_from_diag_m[idx] = false;
                }
            }
            let sm = if ms[left] > NEG_INF { ms[left] + GAP_START } else { NEG_INF };
            let sp = if ps[left] > NEG_INF { ps[left] + GAP_EXTENSION } else { NEG_INF };
            if sm >= sp {
                ps[idx] = sm;
                p_from_m[idx] = true;
            } else {
                ps[idx] = sp;
                p_from_m[idx] = false;
