use crate::fuzzy::fuzzy_indices;
use crate::textarea::TextArea;
use crate::theme::Styles;

const FOOTER_TEXT: &str =
    "Esc, Enter, <Ctrl-m>, <Ctrl-c>: Close | Up, Down, <Ctrl-n>, <Ctrl-p>: cycle through filtered list";

pub enum FuzzyResult {
    None,
    Close,
    /// Select the entry with id
    Select(u32),
}

struct Match {
    id: u32,
    title: String,
    indices: Vec<usize>,
}

pub struct FuzzyPopup {
    query: TextArea,
    entries: Vec<(u32, String)>,
    matches: Vec<Match>,
    state: ListState,
}

impl FuzzyPopup {
    pub fn new(entries: Vec<(u32, String)>) -> Self {
        let mut query = TextArea::default();
        query.set_cursor_line_style(Style::default());
        Self {
            query,
            entries,
            matches: Vec::new(),
            state: ListState::default(),
        }
    }

    fn update_matches(&mut self) -> Option<u32> {
        let q = self.query.lines().first().cloned().unwrap_or_default();
        self.matches.clear();
        if !q.is_empty() {
            let mut scored: Vec<(i32, Match)> = self
                .entries
                .iter()
                .filter_map(|(id, title)| {
                    fuzzy_indices(title, &q).map(|(score, indices)| {
                        (
                            score,
                            Match {
                                id: *id,
                                title: title.clone(),
                                indices,
                            },
                        )
                    })
                })
                .collect();
            scored.sort_by(|a, b| b.0.cmp(&a.0));
            self.matches = scored.into_iter().map(|(_, m)| m).collect();
        }
        if self.matches.is_empty() {
            self.state.select(None);
            None
        } else {
            self.state.select(Some(0));
            Some(self.matches[0].id)
        }
    }

    pub fn render(&mut self, f: &mut Frame, styles: &Styles) {
        let area = centered_rect(60, 60, f.area());
        let block = Block::default()
            .borders(Borders::ALL)
            .border_type(BorderType::Rounded)
            .title("Fuzzy Find");
        f.render_widget(Clear, area);
        let inner = block.inner(area).inner(Margin::new(1, 1));
        f.render_widget(block, area);
        let footer_lines = paragraph_line_count(FOOTER_TEXT, inner.width) as u16;
        let chunks = Layout::vertical([
            Constraint::Length(3),
            Constraint::Min(1),
            Constraint::Length(footer_lines),
        ])
        .split(inner);
        self.query
            .set_block(Block::default().borders(Borders::ALL).title("Search Query"));
        self.query.render(chunks[0], f.buffer_mut());

        let match_style = Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD);
        let items: Vec<ListItem> = self
            .matches
            .iter()
            .map(|m| {
                let spans: Vec<Span> = m
                    .title
                    .chars()
                    .enumerate()
                    .map(|(i, ch)| {
                        if m.indices.contains(&i) {
                            Span::styled(ch.to_string(), match_style)
                        } else {
                            Span::raw(ch.to_string())
                        }
                    })
                    .collect();
                ListItem::new(Line::from(spans))
            })
            .collect();
        let list = List::new(items)
            .block(
                Block::default()
                    .borders(Borders::ALL)
                    .title(format!("Entries: {}", self.matches.len())),
            )
            .highlight_symbol(">> ")
            .highlight_style(Style::from(styles.general.list_highlight_active));
        f.render_stateful_widget(list, chunks[1], &mut self.state);

        let footer = Paragraph::new(FOOTER_TEXT)
            .alignment(Alignment::Center)
            .wrap(Wrap { trim: false });
        f.render_widget(footer, chunks[2]);
    }

    pub fn handle_key(&mut self, key: &KeyEvent) -> FuzzyResult {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let len = self.matches.len();
        match key.code {
            KeyCode::Esc | KeyCode::Enter => return FuzzyResult::Close,
            KeyCode::Char('m') | KeyCode::Char('c') if ctrl => return FuzzyResult::Close,
            KeyCode::Down => return self.cycle(true, len),
            KeyCode::Char('n') if ctrl => return self.cycle(true, len),
            KeyCode::Up => return self.cycle(false, len),
            KeyCode::Char('p') if ctrl => return self.cycle(false, len),
            _ => {}
        }
        if self.query.input(*key) {
            if let Some(id) = self.update_matches() {
                return FuzzyResult::Select(id);
            }
        }
        FuzzyResult::None
    }

    fn cycle(&mut self, forward: bool, len: usize) -> FuzzyResult {
        if len == 0 {
            return FuzzyResult::None;
        }
        let i = match (self.state.selected(), forward) {
            (Some(i), true) => {
                if i + 1 < len {
                    i + 1
                } else {
                    0
                }
            }
            (Some(i), false) => {
                if i == 0 {
                    len - 1
                } else {
                    i - 1
                }
            }
            (None, _) => 0,
        };
        self.state.select(Some(i));
        FuzzyResult::Select(self.matches[i].id)
    }
}
