/// Renders centered, word wrapped lines like the original application did for
/// paragraphs without trimming (continuation lines are offset as if they had one more column).
pub fn render_centered_wrapped(buf: &mut Buffer, area: Rect, lines: &[&str], style: Style) {
    let width = area.width as usize;
    if width == 0 {
        return;
    }
    let mut out: Vec<(String, bool)> = Vec::new();
    for line in lines {
        if line.is_empty() {
            out.push((String::new(), false));
            continue;
        }
        let mut cur = String::new();
        let mut cont = false;
        for word in line.split(' ') {
            let wlen = unicode_width::UnicodeWidthStr::width(word);
            let cur_len = unicode_width::UnicodeWidthStr::width(cur.as_str());
            if cur.is_empty() {
                cur.push_str(word);
            } else if cur_len + 1 + wlen <= width {
                cur.push(' ');
                cur.push_str(word);
            } else {
                out.push((std::mem::take(&mut cur), cont));
                cont = true;
                cur.push_str(word);
            }
        }
        out.push((cur, cont));
    }
    for (i, (text, cont)) in out.iter().enumerate() {
        if i as u16 >= area.height {
            break;
        }
        let lw = unicode_width::UnicodeWidthStr::width(text.as_str()) + if *cont { 1 } else { 0 };
        let offset = (width / 2).saturating_sub(lw / 2);
        let x = area.x + offset as u16;
        let max = width.saturating_sub(offset);
        buf.set_stringn(x, area.y + i as u16, text, max, style);
    }
}
